import {MarketChart} from './chart.js';
import {startProduct} from '/assets/product-client.js';
let productActive=false;

const app=document.querySelector('#app'),modal=document.querySelector('#modal'),toastNode=document.querySelector('#toast');
let sessionExpired=false;
let lang=location.pathname.startsWith('/nb/')?'nb':'en',session=null,state=null,report=null,chart=null,marker=null,busy=false,expandedNews=new Set(),newsFilter='all',toastTimer,activeDialog=null,autoAdvance=false;
const L=(en,nb)=>lang==='nb'?nb:en;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<svg class="icon-svg" aria-hidden="true" focusable="false"><use href="/terminal/icons.svg#${name}"></use></svg>`;
const btn=(label,action,ic='',cls='',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${ic?icon(ic):''}${label}</button>`;
const iconButton=(label,action,ic,extra='')=>btn('',action,ic,'icon',`aria-label="${esc(label)}" title="${esc(label)}" ${extra}`);
const num=(value,d=2)=>Number(value||0).toLocaleString(lang==='nb'?'nb-NO':'en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const money=(minor,currency='USD',digits=2)=>new Intl.NumberFormat(lang==='nb'?'nb-NO':'en-US',{style:'currency',currency,minimumFractionDigits:digits,maximumFractionDigits:digits}).format((minor||0)/100);
const signed=(n,d=2)=>(n>0?'+':'')+num(n,d);
const signClass=n=>n<0?'negative':n>0?'positive':'muted';
const zone=()=>state?.settings?.timezone||'Europe/Oslo';
const time=iso=>iso?new Intl.DateTimeFormat(lang==='nb'?'nb-NO':'en-GB',{timeZone:zone(),hour:'2-digit',minute:'2-digit'}).format(new Date(iso)):'—';
const date=iso=>iso?new Intl.DateTimeFormat(lang==='nb'?'nb-NO':'en-GB',{timeZone:zone(),day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(iso)):'—';
const dateOnly=iso=>iso?new Intl.DateTimeFormat(lang==='nb'?'nb-NO':'en-GB',{timeZone:zone(),year:'numeric',month:'short',day:'2-digit'}).format(new Date(iso)):'—';
const selected=()=>state?.settings?.selectedSymbol||state?.watchlist?.[0]||'NVDA';
const market=()=>state?.markets?.[selected()];
const view=()=>{const v=location.hash.replace('#','').split('?')[0];return ['overview','markets','trade','bots','strategy','research','news','calendar','analytics','reports','settings','alerts'].includes(v)?v:'overview';};
const go=v=>{if(view()===v)render();else location.hash=v;};
const stateName=s=>({stopped:L('Stopped','Stoppet'),starting:L('Starting','Starter'),running:L('Running','Kjører'),paused:L('Paused','Pauset'),blocked:L('Blocked','Blokkert'),error:L('Error','Feil'),pending:L('Pending','Venter'),filled:L('Filled','Utført'),cancelled:L('Cancelled','Kansellert'),rejected:L('Rejected','Avvist'),active:L('Active','Aktiv'),triggered:L('Triggered','Utløst'),allowed:L('Allowed','Tillatt'),wait:L('Wait','Vent')})[s]||s;
const sideName=s=>s==='buy'?L('Buy','Kjøp'):L('Sell','Selg');
const typeName=s=>({market:L('Market','Marked'),limit:L('Limit','Limit'),stop:L('Stop','Stopp')})[s]||s;
function localizedError(e){
  const messages={AUTH_REQUIRED:L('Your session ended. Sign in or refresh to open a guest workspace.','Økten er avsluttet. Logg inn eller oppdater siden for å åpne et gjestearbeidsområde.'),LOGIN_FAILED:L('The email or password was not accepted. Try again.','E-postadressen eller passordet ble ikke godtatt. Prøv igjen.'),ACCOUNT_EXISTS:L('This email already has an account. Sign in instead.','Denne e-postadressen har allerede en konto. Logg inn.'),INVALID_CREDENTIALS:L('Use a valid email and a password of at least 12 characters.','Bruk en gyldig e-postadresse og et passord på minst 12 tegn.'),SIGNUP_DISABLED:L('Public account creation is not open in this release. Continue as guest or sign in to an existing account.','Offentlig kontooppretting er ikke åpen i denne versjonen. Fortsett som gjest eller logg inn på en eksisterende konto.'),CSRF_FAILED:L('Your session changed. Refresh the page and retry.','Økten er endret. Oppdater siden og prøv igjen.'),RATE_LIMITED:L('Too many requests. Wait a moment and retry.','For mange forespørsler. Vent litt og prøv igjen.'),REPLAY_ENDED:L('The fixed sample has ended. It cannot be rewound into this ledger. Export your history to keep it.','Det faste eksemplet er avsluttet og kan ikke spoles tilbake i denne hovedboken. Eksporter historikken for å beholde den.'),ORDER_NOT_PENDING:L('This order is no longer pending and cannot be cancelled.','Ordren venter ikke lenger og kan ikke kanselleres.'),ORDER_NOT_FOUND:L('This paper order was not found. Refresh the workspace.','Papirordren ble ikke funnet. Oppdater arbeidsområdet.'),ALERT_LIMIT:L('Remove an existing alert before adding another.','Fjern et eksisterende varsel før du legger til et nytt.'),ALERT_NOT_FOUND:L('This alert was not found. Refresh the workspace.','Varselet ble ikke funnet. Oppdater arbeidsområdet.'),STATE_CONFLICT:L('Another tab changed this workspace. Retry the same action; the order identifier is preserved.','En annen fane endret arbeidsområdet. Prøv samme handling på nytt; ordreidentifikatoren er beholdt.'),STATE_UNAVAILABLE:L('Your saved workspace could not be loaded. Refresh before changing records.','Det lagrede arbeidsområdet kunne ikke lastes. Oppdater før du endrer registreringer.'),WORKSPACE_COMMAND_LIMIT:L('This workspace reached its saved-action limit. Its existing records and CSV export remain available.','Arbeidsområdet nådde grensen for lagrede handlinger. Eksisterende registreringer og CSV-eksport er fortsatt tilgjengelig.'),WORKSPACE_LIMIT:L('This workspace reached its storage limit. Export your history before opening another guest workspace.','Arbeidsområdet nådde lagringsgrensen. Eksporter historikken før du åpner et nytt gjestearbeidsområde.'),SERVER_NOT_CONFIGURED:L('The trading service has not been configured by the owner. Your request was not saved.','Handelstjenesten er ikke konfigurert av eieren. Forespørselen ble ikke lagret.'),PROVIDER_UNAVAILABLE:L('The configured provider is unavailable. No sample data was substituted.','Den konfigurerte leverandøren er utilgjengelig. Ingen eksempeldata ble satt inn.'),PROVIDER_NOT_CONFIGURED:L('This provider is not connected. The explicit sample workspace remains available.','Leverandøren er ikke tilkoblet. Det tydelig merkede eksempelarbeidsområdet er tilgjengelig.'),CONFIRMATION_REQUIRED:L('Review and confirm the paper order before submitting.','Se gjennom og bekreft papirordren før innsending.'),INVALID_SYMBOL:L('Choose an instrument from the fixed sample catalogue.','Velg et instrument fra det faste eksempelutvalget.'),IDEMPOTENCY_CONFLICT:L('This request identifier was used for different parameters. Edit the order and review it again.','Forespørselsidentifikatoren ble brukt med andre verdier. Rediger ordren og se gjennom den på nytt.'),REQUEST_ID_REUSED:L('This request identifier was already used. Edit and review a new order.','Forespørselsidentifikatoren er brukt tidligere. Rediger og se gjennom en ny ordre.')};
  if(messages[e.code])return messages[e.code];
  if(e.code==='NETWORK_ERROR'||e.code==='BUSY')return e.message;
  if(lang==='en')return e.message||'The request could not be saved. Try again.';
  const exact={'Fast EMA period must be less than slow EMA period.':'Rask EMA-periode må være kortere enn langsom EMA-periode.','Instrument exposure cannot exceed portfolio exposure.':'Instrumenteksponeringen kan ikke overstige porteføljeeksponeringen.','Stop loss must be below the estimated entry.':'Stopptapskurs må være under anslått inngangskurs.','Take profit must be above the estimated entry.':'Gevinstmålet må være over anslått inngangskurs.','Attached exits are available on buy orders only.':'Tilknyttede beskyttelsesordrer er bare tilgjengelige for kjøpsordrer.','Volume multiplier must be 0.1–10.':'Volummultiplikatoren må være fra 0,1 til 10.'};
  if(exact[e.message])return exact[e.message];
  if(e.code==='INVALID_INPUT')return 'Kontroller at antall, beløp og grenser er innenfor feltenes tillatte områder. Rask EMA må være kortere enn langsom EMA, og posisjonsgrensen kan ikke overstige total eksponering.';
  return 'Forespørselen kunne ikke lagres. Oppdater arbeidsområdet og prøv igjen.'+(e.code?` (${e.code})`:'');
}
function reasonText(reason){if(lang==='en'||!reason)return reason;const phrases={'Available cash including fees and pending reservations':'Tilgjengelige kontanter inkludert gebyrer og ventende reservasjoner','Maximum portfolio exposure':'Maksimal porteføljeeksponering','Maximum instrument exposure':'Maksimal instrumenteksponering','Daily marked paper loss limit':'Daglig grense for markedsført papirtap','Daily entry fill limit including pending entries':'Daglig inngangsgrense inkludert ventende innganger','Available whole shares':'Tilgjengelige hele aksjer','Sale proceeds and cash cover fee':'Salgsbeløp og kontanter dekker gebyret','No existing position or pending entry for this instrument':'Ingen eksisterende posisjon eller ventende inngang i instrumentet','Attached stop loss; stop takes precedence when both exits touch.':'Tilknyttet stopptap; stopp gjelder når begge utgangskurser treffes.','Attached profit target':'Tilknyttet gevinstmål','Protective exit filled; competing sale cancelled.':'Beskyttelsesordren ble utført; konkurrerende salg kansellert.'};return String(reason).split('; ').map(p=>phrases[p]||p).join('; ');}
function auditTitle(action){return ({engine_lease_expired:L('Replay lease expired','Avspillingsøkten utløp'),order_rejected_at_fill:L('Order rejected at execution','Ordre avvist ved utførelse'),order_filled:L('Paper order filled','Papirordre utført'),order_cancelled:L('Pending order cancelled','Ventende ordre kansellert'),strategy_evaluated:L('Strategy evaluated','Strategi vurdert'),alert_triggered:L('Price alert triggered','Prisvarsel utløst'),select_symbol:L('Instrument selected','Instrument valgt'),watchlist_add:L('Instrument added to watchlist','Instrument lagt til listen'),watchlist_remove:L('Instrument removed from watchlist','Instrument fjernet fra listen'),watchlist_sort:L('Watchlist sorted','Listen sortert'),settings_update:L('Settings saved','Innstillinger lagret'),strategy_update:L('Strategy saved','Strategi lagret'),engine_start:L('Engine started','Motor startet'),engine_pause:L('Engine paused','Motor pauset'),engine_stop:L('Engine stopped','Motor stoppet'),replay_advance:L('Replay advanced','Avspilling fortsatt'),order_submit:L('Paper order submitted','Papirordre sendt'),order_cancel:L('Order cancelled','Ordre kansellert'),alert_add:L('Alert saved','Varsel lagret'),alert_remove:L('Alert removed','Varsel fjernet'),notifications_read:L('Notifications marked read','Varslinger merket lest')})[action]||L('Account event','Kontohendelse');}
const errorText=e=>localizedError(e);
const titleMap=()=>({overview:L('Overview','Oversikt'),markets:L('Markets','Markeder'),trade:L('Trade','Handle'),bots:L('Trading engine','Handelsmotor'),strategy:L('Strategy','Strategi'),research:L('Signal evidence','Signalgrunnlag'),news:L('News intelligence','Nyhetsoversikt'),calendar:L('Economic calendar','Økonomisk kalender'),analytics:L('Paper analytics','Papiranalyse'),reports:L('Historical report','Historisk rapport'),settings:L('Settings','Innstillinger'),alerts:L('Alerts','Varsler')});
function toast(text){toastNode.textContent=text;toastNode.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastNode.classList.remove('visible'),4500);}
async function api(action,{method='GET',body,requestId}={}){let response;try{response=await fetch(`/.netlify/functions/terminal?action=${action}`,{method,credentials:'same-origin',headers:{...(body?{'Content-Type':'application/json'}:{}),...(session?.csrfToken?{'X-CSRF-Token':session.csrfToken}:{})},...(body?{body:JSON.stringify(body)}:{})});}catch{throw{code:'NETWORK_ERROR',message:L('Connection lost. Your draft is still here; reconnect and try again.','Tilkoblingen ble brutt. Utkastet er beholdt; koble til og prøv igjen.')};}const data=await response.json().catch(()=>({}));if(!response.ok)throw{status:response.status,...(data.error||{message:L('The server could not complete this request.','Serveren kunne ikke fullføre forespørselen.')})};return data;}
async function command(commandData,{message,repaint=true,requestId}={}){if(busy)throw{code:'BUSY',message:L('Wait for the current request to finish.','Vent til den pågående forespørselen er ferdig.')};busy=true;try{const data=await api('command',{method:'POST',body:{requestId:requestId||crypto.randomUUID(),command:commandData}});state=data.state;session.state=state;if(repaint)render();if(message)toast(message);return data.result;}finally{busy=false;}}
function commandUI(data,options){return command(data,options).catch(e=>{toast(errorText(e));if(e.status===401){sessionExpired=true;openAccount();}});}
function glyph(symbol){return `<span class="symbol-glyph" data-symbol="${esc(symbol)}" aria-hidden="true">${esc(symbol==='NVDA'?'N':symbol==='MSFT'?'M':symbol==='AAPL'?'A':symbol==='SPY'?'S':symbol.slice(0,2))}</span>`;}
const checkIcon=pass=>`<span class="${pass?'positive':'amber'}">${icon(pass?'circle-check':'circle-x')}</span>`;
const empty=(title,description)=>`<div class="empty-mini"><strong>${title}</strong>${description}</div>`;
function render(){if(!state)return;const focused=app.contains(document.activeElement)?document.activeElement:null,focusData=focused?.dataset?{...focused.dataset}:null,chartView=chart?{symbol:chart.symbol,timeframe:chart.timeframe,count:chart.count,userZoomed:chart.userZoomed,offset:chart.offset,marker:chart.marker?.time}:null,expanded=!!app.querySelector('.chart-expanded');chart?.destroy();chart=null;document.documentElement.lang=lang;document.title=`${titleMap()[view()]} · Nortivo Trading Platform`;const v=view();app.innerHTML=`${header()}<div class="layout">${sidebar()}<main id="workspace" class="workspace" tabindex="-1">${modebar()}${kpis()}${mobileTabs()}${v==='overview'?overview():page(v)}${footer()}</main></div>`;bindForms();if(v==='overview'){if(expanded)app.querySelector('#chart-panel')?.classList.add('chart-expanded');mountChart();if(chartView&&chart&&chart.symbol===chartView.symbol&&chart.timeframe===chartView.timeframe&&chartView.marker===marker?.time){chart.count=chartView.count;chart.userZoomed=chartView.userZoomed;chart.offset=chartView.offset;chart.draw();}}document.body.classList.toggle('chart-open',expanded&&v==='overview');if(focusData?.action){[...app.querySelectorAll('[data-action]')].find(el=>Object.entries(focusData).every(([k,value])=>el.dataset[k]===value))?.focus();}else if(focusData?.indicator)app.querySelector(`[data-indicator="${focusData.indicator}"]`)?.focus();}
function navlink(v,ic,label,extra=''){return `<a class="navlink ${view()===v?'active':''} ${extra}" href="#${v}" ${view()===v?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></a>`;}
function header(){const titles=titleMap(),unread=(state.notifications||[]).filter(n=>!n.read).length;return `<header class="appbar"><a class="brand" href="/${lang}/" aria-label="${L('Nortivo website','Nortivo-nettstedet')}"><img class="brand-mark nortivo-symbol" src="/assets/brand/nortivo-approved.png" width="39" height="36" alt="">NORTIVO</a><span class="product-name">${L('Trading Platform','Handelsplattform')}</span><nav class="topnav" aria-label="${L('Workspace navigation','Navigasjon i arbeidsområdet')}">${['overview','markets','bots','research','news','reports'].map(v=>`<a href="#${v}" class="${view()===v?'active':''}" ${view()===v?'aria-current="page"':''}>${titles[v]}</a>`).join('')}</nav>${btn(`<span>${L('Search symbols, news…','Søk etter symboler, nyheter…')}</span><kbd>/</kbd>`,'search','search','search-trigger',`aria-label="${L('Search symbols and news','Søk etter symboler og nyheter')}"`)}<span class="badge">${L('Paper only','Kun papirhandel')}</span>${iconButton(`${L('Notifications','Varslinger')}${unread?` (${unread})`:''}`,'notifications','bell',unread?'data-unread="true"':'')}${btn(esc((session.user.name||session.user.email||'G').slice(0,1).toUpperCase()),'account','','profile',`aria-label="${L('Account','Konto')}"`)}</header>`;}
function sidebar(){return `<aside class="sidebar"><nav aria-label="${L('All tools','Alle verktøy')}">${navlink('overview','home',L('Overview','Oversikt'))}${navlink('trade','activity',L('Trade','Handle'))}${navlink('bots','robot',L('Engine','Motor'))}${navlink('strategy','stack-2',L('Strategies','Strategier'))}${navlink('research','file-search',L('Research','Analyse'))}${navlink('news','news',L('News','Nyheter'))}${navlink('calendar','calendar-event',L('Calendar','Kalender'))}${navlink('analytics','chart-histogram',L('Analytics','Statistikk'))}${navlink('reports','chart-bar',L('Reports','Rapporter'))}</nav>${navlink('settings','settings',L('Settings','Innstillinger'),'settings')}</aside>`;}
function modebar(){return `<div class="modebar"><div><span class="badge amber"><span class="dot"></span>${L('FIXED SAMPLE REPLAY','FAST EKSEMPELAVSPILLING')}</span><span>${date(state.replay.asOf)} · ${esc(zone())} · USD</span><span class="guest-disclosure">${session.user.kind==='guest'?L('Guest · virtual USD 100,000 · 1-day session','Gjest · virtuelle USD 100 000 · 1 døgns økt'):L('Private paper account','Privat papirkonto')}</span></div><div>${btn(L('Data & limitations','Data og begrensninger'),'data-info','info-circle')}${session.user.kind==='guest'?btn(L('Sign in / account','Logg inn / konto'),'account','user'):''}</div></div>`;}
function kpis(){const a=state.account,change=a.equityMinor-a.startingCashMinor,pct=a.startingCashMinor?change/a.startingCashMinor*100:0;return `<section class="kpis" aria-label="${L('Your paper account','Din papirkonto')}"><div class="panel kpi"><div class="kpi-label">${L('Paper portfolio value','Papirporteføljens verdi')} ${icon('info-circle')}</div><div class="kpi-value number">${money(a.equityMinor)}</div><div class="kpi-sub ${signClass(change)}">${signed(pct)}% (${change>0?'+':''}${money(change)}) · ${L('your ledger','din hovedbok')}</div></div><div class="panel kpi"><span class="kpi-label">${L('Win rate','Treffprosent')}</span><span class="kpi-value number">${a.winRate===null||a.winRate===undefined?'—':num(a.winRate,1)+'%'}</span><span class="kpi-sub muted">${a.completedTrades?L('Closed trades only','Kun lukkede handler'):L('No closed trades yet','Ingen lukkede handler ennå')}</span></div><div class="panel kpi"><span class="kpi-label">${L('Profit factor','Profittfaktor')}</span><span class="kpi-value number">${a.profitFactor===null||a.profitFactor===undefined?'—':num(a.profitFactor)}</span><span class="kpi-sub muted">${L('Realized gains / losses','Realiserte gevinster / tap')}</span></div><div class="panel kpi featured"><span class="kpi-label">${L('Unrealized paper P&L','Urealisert papirresultat')}</span><span class="kpi-value number ${signClass(a.unrealizedPnlMinor)}">${money(a.unrealizedPnlMinor)}</span><span class="kpi-sub muted">${L('Open positions · USD','Åpne posisjoner · USD')}</span></div><div class="panel kpi"><span class="kpi-label">${L('Completed trades','Fullførte handler')}</span><span class="kpi-value number">${num(a.completedTrades,0)}</span><span class="kpi-sub muted">${L('This paper account','Denne papirkontoen')}</span></div><div class="panel kpi kpi-regime"><div class="regime-icon">${icon('activity')}</div><div><div class="kpi-label">${L('Rule-based market regime','Regelbasert markedstilstand')}</div><div class="kpi-value ${state.regime?.label==='bearish'?'negative':'positive'}">${regimeLabel()}</div><div class="kpi-sub muted">${L('Five-symbol price breadth','Kursbredde · fem symboler')}</div></div></div></section>`;}
function regimeLabel(){return({bullish:L('Positive breadth','Flertall opp'),bearish:L('Negative breadth','Flertall ned'),mixed:L('Mixed breadth','Blandet marked')})[state.regime?.label]||L('Warming up','Bygger datagrunnlag');}
function mobileTabs(){const current=view();return `<nav class="mobile-tabs" aria-label="${L('Mobile workspace','Mobilt arbeidsområde')}">${[['overview','chart-candle',L('Chart','Graf')],['markets','list',L('Markets','Marked')],['news','news',L('News','Nyheter')],['trade','activity',L('Portfolio','Portefølje')],['strategy','robot',L('Strategy','Strategi')],['settings','settings',L('More','Mer')]].map(([v,ic,label])=>`<a href="#${v}" ${current===v?'class="active" aria-current="page"':''}>${icon(ic)}${label}</a>`).join('')}</nav>`;}
function overview(){return `<div class="main-grid"><div class="left-column">${watchlistPanel()}${trendPanel()}</div>${chartPanel()}<div class="right-column">${newsPanel()}${calendarPanel()}</div></div><div class="bottom-grid">${enginePanel()}${signalPanel()}${riskPanel()}${reportPanel()}</div>`;}
function watchlistPanel(){const symbols=[...(state.watchlist||[])];const sort=state.settings.watchlistSort;if(sort==='symbol')symbols.sort();if(sort==='change')symbols.sort((a,b)=>(state.markets[b]?.quote.changePercent||0)-(state.markets[a]?.quote.changePercent||0));return `<section class="panel"><div class="panel-heading"><h2>${L('Watchlist','Overvåkingsliste')}</h2><div class="heading-actions">${iconButton(L('Add symbol','Legg til symbol'),'search','plus')}${iconButton(L('Sort watchlist','Sorter listen'),'watchlist-sort','adjustments-horizontal')}</div></div><div class="segmented">${btn(L('My list','Min liste'),'watchlist-tab','','selected')}${btn(L('All markets','Alle markeder'),'markets')}</div><div class="table-wrap"><table class="watch-table"><thead><tr><th>${L('Symbol','Symbol')}</th><th class="right">${L('Price','Kurs')}</th><th class="right">% ${L('Chg','Endr.')}</th></tr></thead><tbody>${symbols.map(symbol=>{const m=state.markets[symbol];return m?`<tr class="${symbol===selected()?'selected':''}"><td><button data-action="select-symbol" data-symbol="${esc(symbol)}" aria-label="${L('Select','Velg')} ${esc(symbol)}"><span class="watch-symbol">${glyph(symbol)}${esc(symbol)}</span></button></td><td class="right number">${num(m.quote.priceMinor/100)}</td><td class="right number ${signClass(m.quote.changePercent)}">${signed(m.quote.changePercent)}%</td></tr>`:'';}).join('')}</tbody></table>${symbols.length?'':empty(L('Build your watchlist','Bygg overvåkingslisten'),L('Use + to add an instrument.','Bruk + for å legge til et instrument.'))}</div></section>`;}
function trendPanel(){const m=market(),r=state.regime,score=r?.total?Math.round(r.advancing/r.total*100):null;return `<section class="panel"><div class="panel-heading"><h2>${L('Market trend','Markedstrend')}</h2>${iconButton(L('Trend method','Trendmetode'),'trend-info','info-circle')}</div><div class="trend"><div class="trend-score"><strong class="number">${score===null?'—':score+'%'}</strong><span>${L('advancing','stigende')}</span></div><div class="trend-factors"><div class="trend-factor"><span>${L('Universe','Utvalg')}</span><strong>${r?.total??'—'} ${L('symbols','symboler')}</strong></div><div class="trend-factor"><span>${L('Advancing','Stigende')}</span><strong class="positive">${r?.advancing??'—'}</strong></div><div class="trend-factor"><span>${L('Declining','Fallende')}</span><strong class="negative">${r?.declining??'—'}</strong></div><div class="tiny muted">${L('Versus previous session close.','Mot forrige økts sluttkurs.')}</div></div></div></section>`;}
function chartPanel(){const m=market();if(!m)return `<section class="panel chart-panel">${empty(L('Market unavailable','Marked utilgjengelig'),L('Choose another instrument.','Velg et annet instrument.'))}</section>`;const tf=state.settings.timeframe||'5m';return `<section class="panel chart-panel" id="chart-panel" aria-label="${L('Market chart','Markedsgraf')}"><div class="chart-header"><div class="chart-symbol">${glyph(m.symbol)}<strong>${esc(m.symbol)}</strong><span class="chart-company">${esc(m.name)}</span></div><div class="chart-quote"><strong class="chart-price number">${num(m.quote.priceMinor/100)}</strong><span class="chart-change ${signClass(m.quote.changePercent)}">${signed(m.quote.changePercent)}%</span></div><div class="timeframes" role="group" aria-label="${L('Timeframe','Tidsintervall')}">${['1m','5m','15m','1h','4h','1d'].map(value=>btn(value==='1d'?'D':value,'timeframe','',''+(value===tf?'selected':''),`data-value="${value}" aria-pressed="${value===tf}"`)).join('')}${iconButton(L('Expand chart','Utvid grafen'),'chart-fullscreen','arrows-maximize')}</div></div><div class="chart-meta"><div class="chart-indicators">${[['ema9','EMA 9'],['ema20','EMA 20'],['vwap','VWAP']].map(([key,label])=>`<label class="indicator-toggle ${key}"><input type="checkbox" data-indicator="${key}" ${state.settings.indicators?.[key]?'checked':''}>${label}</label>`).join('')}</div><span>USD · ${esc(zone())}</span></div>${chartProvenance(m,tf)}<div class="chart-surface"><canvas tabindex="0" role="img" aria-label="${L('Loading candlestick chart','Laster lysestakegraf')}"></canvas><div class="chart-tooltip"></div><div class="chart-controls" aria-label="${L('Chart controls','Grafkontroller')}"><button data-chart-action="in" aria-label="${L('Zoom in','Zoom inn')}">+</button><button data-chart-action="out" aria-label="${L('Zoom out','Zoom ut')}">−</button><button data-chart-action="reset">${L('Reset view','Tilbakestill visning')}</button></div></div><div class="chart-footer">${btn(L('Trade','Handle'),'order','adjustments-horizontal','primary')}${btn(L('Signals','Signaler'),'research','activity')}${btn(L('News','Nyheter'),'news','news')}${btn(L('Replay +1','Spill +1'),'replay-step','player-skip-forward')}${btn(L('Alerts','Varsler'),'alert','bell')}${btn(L('Data','Data'),'chart-data','list')}</div><details class="chart-data"><summary>${L('Chart data & keyboard guide','Grafdata og tastaturveiledning')}</summary><p class="help">${L('Arrow keys pan; + / − zoom; Home / End move to first / latest known bar. Drag to pan. Scroll to zoom.','Piltaster flytter grafen; + / − zoomer; Home / End viser første / siste kjente datapunkt. Dra for å flytte. Rull for å zoome.')}</p><div class="table-wrap">${barTable(m,tf)}</div></details></section>`;}
function barTable(m,tf){const bars=m[({'1m':'bars','5m':'bars5m','15m':'bars15m','1h':'bars1h','4h':'bars4h','1d':'bars1d'})[tf]]||[];return `<table><caption class="sr-only">${L('Latest 30 available candles in USD','Siste 30 tilgjengelige lysestaker i USD')}</caption><thead><tr><th>${L('Time','Tid')}</th><th>O</th><th>H</th><th>L</th><th>C</th><th>${L('Volume','Volum')}</th></tr></thead><tbody>${bars.slice(-30).map(b=>`<tr><td>${date(b.time)}</td>${[b.open,b.high,b.low,b.close].map(n=>`<td class="number">${num(n/100)}</td>`).join('')}<td>${num(b.volume,0)}</td></tr>`).join('')}</tbody></table>`;}
function chartProvenance(m,tf){const bars=m[({'1m':'bars','5m':'bars5m','15m':'bars15m','1h':'bars1h','4h':'bars4h','1d':'bars1d'})[tf]]||[],last=bars.at(-1),warming=['ema9','ema20'].filter(key=>state.settings.indicators[key]&&!m.indicators.warmup[key]);return `<div class="chart-provenance"><span>${last?L('Completed','Fullførte')+' '+tf+' '+L('bars through','punkter til og med')+' '+date(last.time):L('No completed bars for this timeframe','Ingen fullførte datapunkter for dette intervallet')}</span>${warming.length?`<span class="amber">${warming.map(k=>k==='ema9'?'EMA 9':'EMA 20').join(' / ')}: ${L('warm-up unavailable','utilstrekkelig grunnlag')}</span>`:`<span>${L('Quote','Kurs')}: ${time(m.quote.asOf)}</span>`}</div>`;}
function mountChart(){const container=app.querySelector('.chart-surface');if(!container||!market())return;chart=new MarketChart(container,{t:key=>({warmupChart:L('Not enough completed bars for this timeframe. Try 1m or 5m.','Ikke nok fullførte datapunkter for intervallet. Prøv 1m eller 5m.'),event:L('Published event','Publisert hendelse'),chart:L('candlestick chart','lysestakegraf'),bars:L('bars','datapunkter'),lastPrice:L('Last price','Siste kurs'),chartKeyboard:L('Arrow keys pan. Plus and minus zoom. Data table follows.','Piltaster flytter. Pluss og minus zoomer. Datatabell følger.')})[key]||key,time,date,day:iso=>new Intl.DateTimeFormat(lang==='nb'?'nb-NO':'en-GB',{timeZone:'America/New_York',day:'numeric',month:'short'}).format(new Date(iso))});chart.update(market(),state.settings,marker);}
function newsItems(){const all=state.news||[];return all.filter(n=>newsFilter==='all'||newsFilter==='symbol'&&n.symbols?.includes(selected())||n.category?.toLowerCase()===newsFilter);}
function newsPanel(full=false){return `<section class="panel"><div class="panel-heading"><h2>${icon('news')}${L('News intelligence','Nyhetsoversikt')}</h2>${full?'':`<div class="heading-actions">${iconButton(L('All news','Alle nyheter'),'news','arrow-right')}</div>`}</div><div class="news-filter" role="group" aria-label="${L('News filters','Nyhetsfiltre')}">${[['all',L('All samples','Alle eksempler')],['symbol',selected()],['macro',L('Macro','Makro')],['sector',L('Sector','Sektor')]].map(([key,label])=>btn(esc(label),'news-filter','',newsFilter===key?'selected':'',`data-value="${key}" aria-pressed="${newsFilter===key}"`)).join('')}</div><div class="news-list ${full?'full-news':''}">${newsItems().slice(0,full?50:3).map(n=>`<article class="news-item"><div class="news-art">${icon(n.category==='macro'?'world':n.category==='sector'?'stack-2':'news')}</div><div><button class="news-title" data-action="news-expand" data-id="${esc(n.id)}" aria-expanded="${expandedNews.has(n.id)}">${esc(n.title)}</button><div class="news-time"><time datetime="${esc(n.publishedAt)}">${date(n.publishedAt)}</time> · ${esc(n.category)} <span class="amber">${L('Fictional sample','Fiktivt eksempel')}</span></div></div>${expandedNews.has(n.id)?`<div class="news-summary"><p>${esc(n.summary)}</p><p class="tiny muted">${L('Source','Kilde')}: ${esc(n.source)}. ${L('No machine-generated sentiment or causal claim.','Ingen maskingenerert stemning eller årsakspåstand.')}</p>${btn(L('Show publication on chart','Vis publisering i graf'),'news-chart','chart-candle','',`data-id="${esc(n.id)}"`)} ${n.url&&safeUrl(n.url)?`<a href="${esc(n.url)}" target="_blank" rel="noopener noreferrer">${L('Original source','Originalkilde')} ${icon('external-link')}</a>`:btn(L('Source details','Kildedetaljer'),'news-source','info-circle','',`data-id="${esc(n.id)}"`)}</div>`:''}</article>`).join('')||empty(L('No published items in this filter','Ingen publiserte saker i filteret'),L('Later sample stories appear only when replay reaches their publication time.','Senere eksempelsaker vises først når avspillingen når publiseringstidspunktet.'))}</div>${full?`<div class="panel-body source-line">${L('Fixed fictional fixtures. Live news requires a separately configured, permitted provider. Article text is never a trading instruction.','Faste fiktive eksempler. Løpende nyheter krever en separat konfigurert, tillatt leverandør. Artikkeltekst er aldri en handelsinstruksjon.')} ${btn(L('Provider status','Leverandørstatus'),'integrations','info-circle')}</div>`:''}</section>`;}
function safeUrl(url){try{return ['https:','http:'].includes(new URL(url).protocol);}catch{return false;}}
function calendarPanel(full=false){return `<section class="panel ${full?'full-calendar':''}"><div class="panel-heading"><h2>${icon('calendar-event')}${L('Economic calendar','Økonomisk kalender')}</h2><div class="heading-actions">${full?`<span class="tiny muted">${esc(zone())}</span>`:btn(L('View all','Vis alle'),'calendar','arrow-right')}</div></div><div class="calendar-list">${(state.calendar||[]).slice(0,full?40:3).map(event=>`<article class="calendar-event"><time datetime="${esc(event.scheduledAt)}" class="number">${full?date(event.scheduledAt):time(event.scheduledAt)}</time><span class="country">${esc(event.country)}</span><div>${esc(event.title)}<small>${L('Fictional sample','Fiktivt eksempel')} · ${event.status==='released'?L('Released','Publisert'):L('Scheduled','Planlagt')}</small></div>${full?`<div class="calendar-values"><span>${L('Previous','Forrige')}: ${event.previous??'—'} ${esc(event.unit||'')}</span><span>${L('Forecast','Forventet')}: ${event.forecast??'—'}</span><span>${L('Actual','Faktisk')}: ${event.status==='released'?(event.actual??'—'):'—'}</span></div>`:''}</article>`).join('')||empty(L('No calendar events','Ingen kalenderhendelser'),L('Events are unavailable in this snapshot.','Hendelser er utilgjengelige i dette datasettet.'))}</div>${full?`<div class="panel-body">${btn(L('Change timezone','Endre tidssone'),'settings','world')}<p class="source-line">${L('Scheduled fictional events. Actual values appear only after their release in replay. Live calendar data is not connected.','Planlagte fiktive hendelser. Faktiske verdier vises først etter publisering i avspillingen. Løpende kalenderdata er ikke tilkoblet.')}</p></div>`:''}</section>`;}
function enginePanel(){const e=state.engine||{},running=['running','starting'].includes(e.status);return `<section class="panel"><div class="panel-heading"><h2>${icon('robot')}${L('Paper trading engine','Papirhandelsmotor')}</h2><span class="badge engine-state ${e.status==='blocked'?'amber':''}"><span class="dot"></span>${stateName(e.status||'stopped')}</span></div><div class="engine-layout"><div class="engine-emblem" aria-hidden="true"><img src="/terminal/engine-reference.png" width="128" height="149" alt=""></div><div class="engine-steps"><div class="engine-step"><span>${checkIcon(true)}${L('Fixed sample data','Faste eksempeldata')}</span><span class="muted">${state.replay.cursor}/${state.replay.total}</span></div><div class="engine-step"><span>${checkIcon(true)}${L('EMA trend rules','EMA-trendregler')}</span><span class="muted">v1.0</span></div><div class="engine-step"><span>${checkIcon(e.status!=='blocked')}${L('Server risk checks','Risikokontroll på server')}</span></div><div class="engine-step"><span>${checkIcon(true)}${L('Execution','Utførelse')}</span><span class="positive">${L('Paper only','Kun papir')}</span></div></div></div><div class="engine-mode">${state.strategy.autoTrade?L('Automatic paper entries: ON','Automatiske papirinnganger: PÅ'):L('Automatic paper entries: OFF · evidence only','Automatiske papirinnganger: AV · kun grunnlag')}</div><div class="engine-controls">${btn(running?L('Pause','Pause'):L('Start','Start'),running?'engine-pause':'engine-start',running?'player-pause':'player-play','primary')}${btn(L('Stop','Stopp'),'engine-stop','player-stop')}${btn(L('+1 bar','+1 punkt'),'replay-step','player-skip-forward')}${btn(L('Configure','Konfigurer'),'strategy','settings')}</div><div class="engine-description">${L('In-tab replay. Pauses when this tab is hidden; no background worker.','Avspilling i fanen. Pauses når fanen skjules; ingen bakgrunnsprosess.')}</div></section>`;}
function latestSignal(){return [...(state.signals||[])].reverse().find(s=>s.symbol===selected())||null;}
function conditionName(condition){const id=String(condition.id||'');const names={'price-trend':L('Close above fast EMA','Sluttkurs over rask EMA'),'ema-trend':L('Fast EMA above slow EMA','Rask EMA over langsom EMA'),vwap:L('Close above session VWAP','Sluttkurs over øktens VWAP'),volume:L('Volume ≥ preceding 20-bar mean','Volum ≥ snittet for 20 foregående punkter'),warmup:L('Indicator warm-up','Indikatorgrunnlag')};return names[id]||L(condition.label,'Regel: '+(condition.id||condition.label));}
function conditionValue(value,id){return value===null||value===undefined?'—':id==='volume'?num(value,0):money(value);}
function signalPanel(){const s=latestSignal();return `<section class="panel"><div class="panel-heading"><h2>${icon('activity')}${L('Signal details','Signaldetaljer')}</h2><div class="heading-actions"><span class="tiny muted">${s?time(s.time):'—'}</span>${s?iconButton(L('Inspect signal evidence','Undersøk signalgrunnlaget'),'signal-detail','arrow-right',`data-id="${esc(s.id)}"`):''}</div></div>${s?`<div class="signal-content"><div><strong class="${s.decision==='allowed'?'positive':'amber'}">${stateName(s.decision)}</strong> · ${esc(s.symbol)}<div class="signal-price-row"><span>${L('Reference','Referanse')}</span><span class="number">${num(s.priceMinor/100)}</span></div><div class="signal-price-row"><span>${L('Quantity','Antall')}</span><span class="number">${s.quantity}</span></div><div class="signal-price-row"><span>${L('Target','Mål')}</span><span class="number">${s.takeProfitMinor?num(s.takeProfitMinor/100):'—'}</span></div><div class="signal-price-row"><span>${L('Stop','Stopp')}</span><span class="number">${s.stopLossMinor?num(s.stopLossMinor/100):'—'}</span></div><div class="tiny muted">${s.conditionsMet}/${s.conditionsTotal} ${L('conditions met','vilkår oppfylt')}</div></div><div class="signal-rules">${(s.conditions||[]).filter(c=>c.enabled!==false).slice(0,4).map(c=>`<div class="signal-condition">${checkIcon(c.met)}<span>${esc(conditionName(c))}</span></div>`).join('')}${btn(L('View evidence','Se grunnlaget'),'signal-detail','','',`data-id="${esc(s.id)}"`)}</div></div>`:empty(L('Inspect what the rules knew','Se hva reglene visste'),L('Start the engine, then advance replay. Each evaluation records its timestamp, conditions and risk checks.','Start motoren og fortsett avspillingen. Hver vurdering lagrer tidspunkt, vilkår og risikokontroll.'))}</section>`;}
function riskPanel(){const risk=state.risk,exposure=state.account.equityMinor?Math.max(0,(state.account.equityMinor-state.account.cashMinor)/state.account.equityMinor*100):0;const lossUsed=risk.maxDailyLossMinor?Math.min(100,Math.max(0,-risk.dailyPnlMinor/risk.maxDailyLossMinor*100)):0;const blocked=(risk.checks||[]).some(c=>!c.passed);return `<section class="panel"><div class="panel-heading"><h2>${icon('shield-check')}${L('Risk management','Risikostyring')}</h2><div class="heading-actions">${iconButton(L('Edit risk limits','Endre risikogrenser'),'risk-settings','settings')}</div></div><div class="risk-lines">${[[L('Portfolio exposure','Porteføljeeksponering'),exposure,num(exposure,0)+'%'],[L('Daily loss limit used','Daglig tapsgrense brukt'),lossUsed,num(lossUsed,0)+'%'],[L('Max. position size','Maks. posisjonsstørrelse'),risk.maxPositionBps/100,num(risk.maxPositionBps/100,0)+'%']].map(([label,value,display])=>`<div class="risk-line"><span>${label}</span><progress class="risk-progress" max="100" value="${Math.min(100,Math.max(0,value))}" aria-label="${label}">${display}</progress><span class="right number">${display}</span></div>`).join('')}</div><div class="risk-footer ${blocked?'amber':'positive'}">${icon(blocked?'info-circle':'circle-check')}${blocked?L('A risk limit needs attention','En risikogrense krever oppmerksomhet'):L('Limits enforced before every order','Grenser kontrolleres før hver ordre')}</div><div class="engine-description">${L('Daily loss cap','Daglig tapsgrense')}: ${money(risk.maxDailyLossMinor)} · ${L('Max exposure','Maks. eksponering')}: ${num(risk.maxExposureBps/100,0)}%</div></section>`;}
function reportPanel(){return `<section class="panel"><div class="panel-heading"><h2>${icon('chart-bar')}${L('Reported history · 2026','Rapportert historikk · 2026')}</h2><div class="heading-actions">${iconButton(L('Full historical report','Full historisk rapport'),'reports','arrow-right')}</div></div>${report?`<div class="report-summary"><div class="report-return number">+${num(report.returnOnOpeningEquityPercent)}%</div><div class="report-row"><span>${L('Trading P&L','Handelsresultat')}</span><span class="number">${money(report.profitOre,'NOK',0)}</span></div><div class="report-row"><span>${L('Sessions / trades','Økter / handler')}</span><span class="number">${report.sessions} / ${num(report.trades,0)}</span></div><div class="report-row"><span>${L('Avg. / session · deployed','Snitt / økt · investert')}</span><span class="positive number">+${num(report.averageDeployedDailyPercent)}%</span></div><div class="report-footnote">${L('Company reported history · NOK. Separate from your paper account.','Selskapets rapporterte historikk · NOK. Adskilt fra papirkontoen din.')}</div></div>`:empty(L('Historical report loading','Laster historisk rapport'),L('Your paper account remains separate.','Papirkontoen din er adskilt.'))}</section>`;}
function footer(){return `<footer class="statusbar"><span><span class="dot positive"></span>${L('Server-owned paper ledger','Serverlagret papirhovedbok')} · ${L('Replay','Avspilling')} ${state.replay.cursor}/${state.replay.total}</span><span>${L('Fixed fictional sample · Simulated fills · Real-money execution disabled','Fast fiktivt eksempel · Simulert utførelse · Handel med ekte penger deaktivert')} · <a href="/${lang}/report-2026/">${L('Report, risk & methodology','Rapport, risiko og metode')}</a> · <a href="/${lang}/">${L('Website','Nettsted')}</a> · <a href="/${lang}/privacy/">${L('Privacy','Personvern')}</a></span></footer>`;}
function page(v){const titles=titleMap();const descriptions={markets:L('Search the fixed instrument catalogue and build your persistent watchlist. All quotes below are fictional sample prices in USD.','Søk i det faste instrumentutvalget og bygg en lagret overvåkingsliste. Alle kurser er fiktive eksempelkurser i USD.'),trade:L('Submit confirmed paper orders against the current sample replay. Orders fill at the next eligible bar, with configured costs.','Send bekreftede papirordrer i eksempelavspillingen. Ordrer utføres ved neste aktuelle datapunkt med konfigurerte kostnader.'),bots:L('An understandable EMA example strategy. In-tab playback only; no durable service runs after you leave.','En forståelig EMA-eksempelstrategi. Avspilling kun i fanen; ingen tjeneste fortsetter etter at du går ut.'),strategy:L('Configure deterministic rules and server-enforced risk. This example is not a proven profitable strategy.','Konfigurer faste regler og serverkontrollert risiko. Eksemplet er ikke en dokumentert lønnsom strategi.'),research:L('Inspect the exact snapshot, rule conditions and risk checks behind each evaluation.','Undersøk det konkrete datagrunnlaget, regelvilkårene og risikokontrollen bak hver vurdering.'),news:L('Only stories already published at the replay cursor are visible. These are clearly labeled fictional samples.','Kun saker publisert før avspillingstidspunktet er synlige. Dette er tydelig merkede fiktive eksempler.'),calendar:L('Fictional scheduled events in your chosen timezone. Later actual values remain unavailable until release.','Fiktive planlagte hendelser i valgt tidssone. Senere faktiske verdier er skjult frem til publisering.'),analytics:L('Metrics from your own paper ledger, including genuine simulated losses, fills and fees.','Tall fra din egen papirhovedbok, inkludert reelle simulerte tap, handler og gebyrer.'),reports:L('Nortivo’s reported 2026 history in NOK. It does not belong to this paper account or prove this example engine produced those results.','Nortivos rapporterte historikk for 2026 i NOK. Den tilhører ikke papirkontoen og viser ikke at denne eksempelmotoren skapte resultatene.'),settings:L('Preferences, account storage and honest integration status. All saved preferences are private to your server session.','Preferanser, kontolagring og faktisk tilkoblingsstatus. Lagrede preferanser er private for serverøkten din.'),alerts:L('Server-evaluated sample price alerts. Alerts trigger only when the replay reaches a matching known price.','Prisvarsler som vurderes av serveren. De utløses først når avspillingen når en kjent kurs som oppfyller vilkåret.')};return `<div class="page-content"><div class="page-heading"><div><h1>${titles[v]}</h1><p>${descriptions[v]||''}</p></div>${v==='trade'?btn(L('New paper order','Ny papirordre'),'order','plus','primary'):v==='alerts'?btn(L('Create alert','Opprett varsel'),'alert','plus','primary'):btn(L('Back to chart','Tilbake til grafen'),'overview','chart-candle')}</div>${({markets:marketPage,trade:portfolioPage,bots:enginePage,strategy:strategyPage,research:researchPage,news:()=>newsPanel(true),calendar:()=>calendarPanel(true),analytics:analyticsPage,reports:reportsPage,settings:settingsPage,alerts:alertsPage})[v]?.()||''}</div>`;}
function marketPage(){return `<section class="panel page-panel"><label class="field"><span>${L('Search instruments','Søk etter instrumenter')}</span><input class="filter-input" id="market-search" placeholder="${L('Symbol or company name','Symbol eller selskapsnavn')}" autocomplete="off"></label><div class="market-list">${(state.catalog||[]).map(item=>{const m=state.markets[item.symbol],favorite=state.watchlist.includes(item.symbol);return `<div class="market-row" data-market-text="${esc((item.symbol+' '+item.name).toLowerCase())}"><div><button class="ghost" data-action="select-symbol" data-symbol="${esc(item.symbol)}"><span class="watch-symbol">${glyph(item.symbol)}${esc(item.symbol)}</span></button><small>${esc(item.name)} · USD</small></div><span class="number right">${m?num(m.quote.priceMinor/100):'—'}</span><span class="number right ${signClass(m?.quote.changePercent)}">${m?signed(m.quote.changePercent)+'%':'—'}</span>${btn(favorite?L('Remove','Fjern'):L('Add','Legg til'),favorite?'watchlist-remove':'watchlist-add',favorite?'check':'plus',favorite?'selected':'',`data-symbol="${esc(item.symbol)}" aria-label="${favorite?L('Remove','Fjern'):L('Add','Legg til')} ${esc(item.symbol)}"`)}</div>`;}).join('')}</div><p class="form-note">${L('Source: Nortivo fixed fictional sample · Exchange session: America/New_York · All displayed price and volume data share the same unadjusted synthetic basis. No actual security quote is represented.','Kilde: Nortivos faste fiktive eksempel · Børsøkt: America/New_York · Kurs og volum har samme ujusterte syntetiske grunnlag. Ingen faktisk verdipapirkurs vises.')}</p></section>`;}
function positionsTable(){return `<div class="table-wrap"><table class="view-table"><thead><tr>${[L('Symbol','Symbol'),L('Shares','Aksjer'),L('Avg. price','Snittkurs'),L('Market value','Markedsverdi'),L('Unrealized P&L','Urealisert resultat'),''].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${(state.positions||[]).map(p=>`<tr><td><strong>${esc(p.symbol)}</strong></td><td class="number">${p.quantity}</td><td class="number">${money(p.averagePriceMinor)}</td><td class="number">${money(p.marketValueMinor)}</td><td class="number ${signClass(p.unrealizedPnlMinor)}">${money(p.unrealizedPnlMinor)}</td><td>${btn(L('Sell','Selg'),'order-sell','','',`data-symbol="${esc(p.symbol)}" data-quantity="${p.quantity}"`)}</td></tr>`).join('')||`<tr><td colspan="6" class="list-empty">${L('No open positions. Submit a paper order, then advance replay to reach its next eligible fill.','Ingen åpne posisjoner. Send en papirordre og fortsett avspillingen til neste aktuelle utførelse.')}</td></tr>`}</tbody></table></div>`;}
function ordersTable(){return `<div class="table-wrap"><table class="view-table"><thead><tr>${[L('Time','Tid'),L('Order','Ordre'),L('Type','Type'),L('Shares','Aksjer'),L('Price','Kurs'),L('Status','Status'),''].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${[...(state.orders||[])].reverse().map(o=>`<tr><td>${date(o.submittedAt)}</td><td>${sideName(o.side)} <strong>${esc(o.symbol)}</strong></td><td>${typeName(o.orderType)}</td><td class="number">${o.quantity}</td><td class="number">${o.fillPriceMinor?money(o.fillPriceMinor):o.limitPriceMinor?money(o.limitPriceMinor):o.stopPriceMinor?money(o.stopPriceMinor):'—'}</td><td><span class="${o.status==='rejected'?'negative':o.status==='filled'?'positive':'muted'}">${stateName(o.status)}</span>${o.reason?`<small class="help"> ${esc(reasonText(o.reason))}</small>`:''}</td><td>${o.status==='pending'?btn(L('Cancel','Kanseller'),'order-cancel','','danger',`data-id="${esc(o.id)}"`):o.feeMinor?`<span class="help">${L('Fee','Gebyr')}: ${money(o.feeMinor)}</span>`:''}</td></tr>`).join('')||`<tr><td colspan="7" class="list-empty">${L('Your submitted orders appear here.','Innsendte ordrer vises her.')}</td></tr>`}</tbody></table></div>`;}
function ledgerTable(){return `<div class="table-wrap"><table class="view-table"><thead><tr><th>${L('Time','Tid')}</th><th>${L('Entry','Postering')}</th><th>${L('Symbol','Symbol')}</th><th>${L('Amount','Beløp')}</th><th>${L('Cash after','Kontanter etter')}</th></tr></thead><tbody>${[...(state.ledger||[])].reverse().map(l=>`<tr><td>${date(l.time)}</td><td>${({deposit:L('Virtual deposit','Virtuelt innskudd'),buy:L('Paper buy','Papirkjøp'),sell:L('Paper sell','Papirsalg'),fee:L('Execution fee','Utførelsesgebyr')})[l.type]||esc(l.type)}</td><td>${esc(l.symbol||'—')}</td><td class="number ${signClass(l.amountMinor)}">${money(l.amountMinor)}</td><td class="number">${money(l.cashAfterMinor)}</td></tr>`).join('')}</tbody></table></div>`;}
function portfolioPage(){const a=state.account;return `<section class="panel page-panel"><div class="metric-inline"><div><span>${L('Available virtual cash','Tilgjengelige virtuelle kontanter')}</span><strong>${money(a.availableCashMinor??a.cashMinor)}</strong></div><div><span>${L('Reserved for pending orders','Reservert for ventende ordrer')}</span><strong>${money(a.reservedMinor||0)}</strong></div><div><span>${L('Realized paper P&L','Realisert papirresultat')}</span><strong class="${signClass(a.realizedPnlMinor)}">${money(a.realizedPnlMinor)}</strong></div><div><span>${L('Fees paid','Betalte gebyrer')}</span><strong>${money(a.feesMinor)}</strong></div></div><p class="source-line">${L('USD virtual funds. Orders fill on the next eligible known bar, with configured fees and slippage. Paper fills do not reproduce real liquidity.','Virtuelle USD. Ordrer utføres ved neste aktuelle kjente datapunkt, med valgte gebyrer og prisglidning. Papirutførelse gjenskaper ikke faktisk likviditet.')}</p><div class="form-actions">${btn(L('Advance 1 bar','Fortsett 1 punkt'),'replay-step','player-skip-forward')}${btn(L('Advance 10 bars','Fortsett 10 punkter'),'replay-ten','player-skip-forward')}${btn(L('Export history CSV','Eksporter historikk CSV'),'export','download')}</div></section><section class="panel mt-12"><div class="panel-heading"><h2>${L('Open positions','Åpne posisjoner')}</h2></div>${positionsTable()}</section><section class="panel mt-12"><div class="panel-heading"><h2>${L('Orders & execution','Ordrer og utførelse')}</h2></div>${ordersTable()}</section><section class="panel mt-12"><div class="panel-heading"><h2>${L('Transaction ledger','Transaksjonshovedbok')}</h2></div>${ledgerTable()}</section>`;}
function enginePage(){return `<div class="page-grid equal"><div>${enginePanel()}<section class="panel page-panel mt-12"><h2>${L('Replay controls','Avspillingskontroller')}</h2><p>${L('Start enables deterministic strategy evaluation as sample bars advance. Auto execution is an explicit strategy setting. Pause halts new evaluations; existing pending orders and protective exits still apply when you manually advance. Stop also cancels pending strategy orders.','Start aktiverer faste strategivurderinger når eksempelpunkter spilles av. Automatisk utførelse er en egen strategiinnstilling. Pause stanser nye vurderinger; eksisterende ventende ordrer og beskyttelsesordrer gjelder fortsatt ved manuell avspilling. Stopp kansellerer også ventende strategiordrer.')}</p><div class="form-actions">${btn(L('Advance 1 bar','Fortsett 1 punkt'),'replay-step','player-skip-forward')}${btn(L('Advance 10 bars','Fortsett 10 punkter'),'replay-ten','player-skip-forward')}${btn(L('Advance 30 bars','Fortsett 30 punkter'),'replay-thirty','player-skip-forward')}</div><p class="form-note">${L('Last known sample time','Siste kjente eksempeltidspunkt')}: ${date(state.replay.asOf)} · ${state.replay.cursor}/${state.replay.total}. ${L('No future data is exposed to the strategy.','Strategien får ikke tilgang til fremtidige data.')}</p></section></div><section class="panel page-panel"><h2>${L('Engine audit trail','Motorens hendelseslogg')}</h2>${auditList((state.audit||[]).slice(-15).reverse())}</section></div>`;}
const field=(label,name,value,type='number',extra='',note='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}>${note?`<small>${note}</small>`:''}</label>`;
function strategyPage(){const s=state.strategy,r=state.risk;return `<div class="page-grid equal"><section class="panel page-panel"><h2>${L('EMA trend · example v1.0','EMA-trend · eksempel v1.0')}</h2><p>${L('Evaluates completed 1-minute sample bars. A long signal requires fast EMA above slow EMA and price above the fast EMA, plus any enabled filters. The next known bar supplies execution, never the signal candle’s future price.','Vurderer fullførte eksempelpunkter på ett minutt. Et kjøpssignal krever rask EMA over langsom EMA og kurs over rask EMA, samt valgte filtre. Neste kjente datapunkt gir utførelsen, aldri en fremtidig pris i signalpunktet.')}</p><form id="strategy-form"><div class="form-grid mt-15">${field(L('Fast EMA period','Rask EMA-periode'),'fastPeriod',s.fastPeriod,'number','min="2" max="100" required')}${field(L('Slow EMA period','Langsom EMA-periode'),'slowPeriod',s.slowPeriod,'number','min="3" max="200" required')}${field(L('Shares per entry','Aksjer per inngang'),'quantity',s.quantity,'number','min="1" max="100000" step="1" required')}${field(L('Volume multiplier','Volummultiplikator'),'volumeMultiplier',s.volumeMultiplier,'number','min="0.1" max="10" step="0.1" required')}${field(L('Stop distance (%)','Stoppavstand (%)'),'stopLossPercent',s.stopLossBps/100,'number','min="0.1" max="50" step="0.1" required')}${field(L('Target distance (%)','Målavstand (%)'),'takeProfitPercent',s.takeProfitBps/100,'number','min="0.1" max="100" step="0.1" required')}</div><div class="mt-12"><label class="check-field"><input name="useVwap" type="checkbox" ${s.useVwap?'checked':''}>${L('Require price above session VWAP','Krev kurs over øktens VWAP')}</label><label class="check-field"><input name="useVolume" type="checkbox" ${s.useVolume?'checked':''}>${L('Enable volume filter','Aktiver volumfilter')}</label><label class="check-field"><input name="autoTrade" type="checkbox" ${s.autoTrade?'checked':''}>${L('Submit allowed signals as paper orders','Send tillatte signaler som papirordrer')}</label></div><div class="form-actions"><button class="primary" type="submit">${L('Save strategy','Lagre strategi')}</button>${btn(L('Open engine','Åpne motor'),'bots','robot')}</div><div class="inline-error" data-form-error role="alert"></div></form></section><section class="panel page-panel" id="risk-form-panel"><h2>${L('Server-enforced risk controls','Serverkontrollerte risikogrenser')}</h2><form id="risk-form"><div class="form-grid">${field(L('Maximum exposure (%)','Maksimal eksponering (%)'),'maxExposurePercent',r.maxExposureBps/100,'number','min="1" max="100" step="1" required')}${field(L('Maximum single position (%)','Maksimal enkeltposisjon (%)'),'maxPositionPercent',r.maxPositionBps/100,'number','min="1" max="100" step="1" required')}${field(L('Daily loss cap (USD)','Daglig tapsgrense (USD)'),'maxDailyLoss',r.maxDailyLossMinor/100,'number','min="1" max="100000" step="0.01" required')}${field(L('Trades per day','Handler per dag'),'maxTradesPerDay',r.maxTradesPerDay,'number','min="1" max="500" step="1" required')}${field(L('Fee per order (USD)','Gebyr per ordre (USD)'),'fee',r.feePerOrderMinor/100,'number','min="0" max="1000" step="0.01" required')}${field(L('Slippage (basis points)','Prisglidning (basispunkter)'),'slippageBps',r.slippageBps,'number','min="0" max="500" step="1" required')}</div><div class="form-actions"><button class="primary" type="submit">${L('Save risk limits','Lagre risikogrenser')}</button></div><div class="inline-error" data-form-error role="alert"></div></form><div class="callout warning">${L('A risk limit can reject an order. Existing positions can still lose value; these controls do not guarantee a maximum realized loss or real execution quality.','En risikogrense kan avvise en ordre. Eksisterende posisjoner kan fortsatt tape verdi; grensene garanterer ikke et maksimalt faktisk tap eller virkelig utførelseskvalitet.')}</div><p class="form-note">${L('Daily risk boundary uses America/New_York exchange dates. Display timezone changes presentation only.','Daglig risikogrense følger børsdatoer i America/New_York. Visningens tidssone endrer bare presentasjonen.')}</p></section></div>`;}
function auditList(rows){return `<div class="audit-list">${rows.map(a=>`<div class="audit-row"><span>${esc(auditTitle(a.action||a.type))}${a.message?`<small class="help"> · ${esc(a.message)}</small>`:''}${a.symbol?` · ${esc(a.symbol)}`:''}</span><time>${date(a.time||a.at)}</time></div>`).join('')||empty(L('No actions recorded yet','Ingen handlinger lagret ennå'),L('Your saved actions and evaluations will appear here.','Lagrede handlinger og vurderinger vises her.'))}</div>`;}
function researchPage(){return `<div class="page-grid"><section class="panel"><div class="panel-heading"><h2>${L('Recorded rule evaluations','Lagrede regelvurderinger')}</h2></div><div class="table-wrap"><table class="view-table"><thead><tr><th>${L('Time','Tid')}</th><th>${L('Symbol','Symbol')}</th><th>${L('Conditions','Vilkår')}</th><th>${L('Decision','Beslutning')}</th><th></th></tr></thead><tbody>${[...(state.signals||[])].reverse().map(s=>`<tr><td>${date(s.time)}</td><td>${esc(s.symbol)}</td><td>${s.conditionsMet}/${s.conditionsTotal} ${L('met','oppfylt')}</td><td class="${s.decision==='allowed'?'positive':s.decision==='blocked'?'negative':'muted'}">${stateName(s.decision)}</td><td>${btn(L('Evidence','Grunnlag'),'signal-detail','file-search','',`data-id="${esc(s.id)}"`)}</td></tr>`).join('')||`<tr><td colspan="5" class="list-empty">${L('Start the engine and advance replay to generate reproducible evaluations.','Start motoren og fortsett avspillingen for å lage reproduserbare vurderinger.')}</td></tr>`}</tbody></table></div></section><div>${signalPanel()}<section class="panel page-panel mt-12"><h2>${L('No invented confidence score','Ingen oppdiktet sikkerhetsprosent')}</h2><p>${L('Condition agreement is a count, not a probability of profit. Each record retains the known data timestamp, version, thresholds and server risk checks. The AI explanation service is not connected.','Regelenighet er et antall, ikke en sannsynlighet for gevinst. Hver registrering bevarer kjent datatidspunkt, versjon, terskler og serverkontroll. Tjenesten for KI-forklaringer er ikke tilkoblet.')}</p></section></div></div>`;}
function analyticsPage(){const a=state.account;return `<section class="panel page-panel"><div class="metric-inline"><div><span>${L('Realized P&L','Realisert resultat')}</span><strong class="${signClass(a.realizedPnlMinor)}">${money(a.realizedPnlMinor)}</strong></div><div><span>${L('Unrealized P&L','Urealisert resultat')}</span><strong class="${signClass(a.unrealizedPnlMinor)}">${money(a.unrealizedPnlMinor)}</strong></div><div><span>${L('Fees','Gebyrer')}</span><strong>${money(a.feesMinor)}</strong></div><div><span>${L('Completed trades','Fullførte handler')}</span><strong>${a.completedTrades}</strong></div></div><div class="callout">${L('Period: this paper account since its virtual opening deposit. Win rate uses closed trades; profit factor is realized gross gains divided by realized gross losses. Undefined metrics remain blank.','Periode: denne papirkontoen siden det virtuelle åpningsinnskuddet. Treffprosent bruker lukkede handler; profittfaktor er realiserte brutto gevinster delt på realiserte brutto tap. Udefinerte tall er tomme.')}</div>${a.completedTrades?'':`<p>${L('No completed trades yet. Your first confirmed buy and subsequent sell will establish realized results. The historical Nortivo report is never used to fill this account’s metrics.','Ingen fullførte handler ennå. Første bekreftede kjøp og påfølgende salg vil gi realiserte resultater. Nortivos historiske rapport fyller aldri denne kontoens tall.')}</p>`}<div class="form-actions">${btn(L('View positions & ledger','Se posisjoner og hovedbok'),'trade','list')}${btn(L('Export trade history','Eksporter handelshistorikk'),'export','download')}</div></section><section class="panel page-panel mt-12"><h2>${L('Account audit events','Kontohendelser')}</h2>${auditList([...(state.audit||[])].slice(-30).reverse())}</section>`;}
function reportsPage(){if(!report)return `<section class="panel page-panel">${L('The report source is unavailable. Reload to try again. Your paper account is unaffected.','Rapportkilden er utilgjengelig. Last inn på nytt for å prøve igjen. Papirkontoen er upåvirket.')}</section>`;return `<div class="page-grid equal"><section class="panel page-panel"><h2>${L('Nortivo reported history · 2026','Nortivos rapporterte historikk · 2026')}</h2><div class="report-return number">+${num(report.returnOnOpeningEquityPercent)}%</div><p class="source-line">${dateOnly(report.start)} – ${dateOnly(report.end)} · NOK · ${L('Reported historical information','Rapportert historisk informasjon')}</p><dl class="detail-list">${[[L('Opening equity','Åpningskapital'),money(report.openingEquityOre,'NOK')],[L('Closing equity','Sluttkapital'),money(report.closingEquityOre,'NOK')],[L('Trading profit after costs','Handelsresultat etter kostnader'),money(report.profitOre,'NOK')],[L('Maximum drawdown','Maksimal nedgang'),num(report.maxDrawdownPercent)+'%'],[L('Reported sessions','Rapporterte økter'),report.sessions],[L('Reported trades','Rapporterte handler'),num(report.trades,0)]].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl><a class="badge" href="/${lang}/report-2026/">${L('Full report, risk & methodology','Full rapport, risiko og metode')} ${icon('external-link')}</a></section><section class="panel page-panel"><h2>${L('Two distinct session-return bases','To ulike grunnlag for øktavkastning')}</h2><div class="report-return number">+${num(report.averageDeployedDailyPercent)}%</div><p>${L('Average session return on deployed capital · Reported historical average.','Gjennomsnittlig øktavkastning på investert kapital · Rapportert historisk gjennomsnitt.')}</p><div class="detail-list"><div><dt>${L('Average session on account equity','Gjennomsnitt per økt på kontokapital')}</dt><dd>+${num(report.averageAccountDailyPercent,4)}%</dd></div><div><dt>${L('Source','Kilde')}</dt><dd><a href="/report-2026/summary.json">summary.json</a></dd></div></div><div class="callout warning">${L('Reported history is not independent audit or broker verification. Past results do not guarantee future performance. The new sample engine and your virtual USD paper account are separate from these NOK records.','Rapportert historikk er ikke en uavhengig revisjon eller meglerbekreftelse. Tidligere resultater garanterer ikke fremtidig avkastning. Den nye eksempelmotoren og din virtuelle papirkonto i USD er adskilt fra disse NOK-postene.')}</div><a href="${esc(report.sourcePdf)}" target="_blank" rel="noopener">${L('Read the source PDF','Les den opprinnelige PDF-en')} ${icon('external-link')}</a></section></div>`;}
function settingsPage(){return `<nav class="settings-tools" aria-label="${L('Additional workspace tools','Flere verktøy')}">${[['bots','robot'],['research','file-search'],['calendar','calendar-event'],['analytics','chart-histogram'],['reports','chart-bar'],['alerts','bell']].map(([v,ic])=>btn(titleMap()[v],v,ic)).join('')}</nav><div class="page-grid equal"><section class="panel page-panel"><h2>${L('Workspace preferences','Arbeidsinnstillinger')}</h2><form id="settings-form"><div class="form-grid"><label class="field"><span>${L('Language','Språk')}</span><select name="language"><option value="en" ${lang==='en'?'selected':''}>English</option><option value="nb" ${lang==='nb'?'selected':''}>Norsk bokmål</option></select></label><label class="field"><span>${L('Display timezone','Tidssone for visning')}</span><select name="timezone">${['Europe/Oslo','America/New_York','Europe/London','Asia/Tokyo','UTC'].map(z=>`<option value="${z}" ${zone()===z?'selected':''}>${z}</option>`).join('')}</select></label><label class="field"><span>${L('Watchlist ordering','Rekkefølge i overvåkingslisten')}</span><select name="watchlistSort">${[['manual',L('Added order','Lagt til')],['symbol',L('Symbol A–Z','Symbol A–Å')],['change',L('Price change','Kursendring')]].map(([v,label])=>`<option value="${v}" ${state.settings.watchlistSort===v?'selected':''}>${label}</option>`).join('')}</select></label><label class="field"><span>${L('Default chart timeframe','Standardintervall for graf')}</span><select name="timeframe">${['1m','5m','15m','1h','4h','1d'].map(t=>`<option ${state.settings.timeframe===t?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="form-actions"><button class="primary" type="submit">${L('Save preferences','Lagre innstillinger')}</button></div><div class="inline-error" data-form-error role="alert"></div></form><p class="form-note">${L('Price currency remains USD; historical reported values remain NOK. Changing language or timezone does not convert money or alter historical records.','Kursvaluta er fortsatt USD; historiske rapporttall er fortsatt NOK. Endring av språk eller tidssone konverterer ikke penger og endrer ikke historiske registreringer.')}</p></section><section class="panel page-panel"><h2>${L('Account & storage','Konto og lagring')}</h2><div class="account-identity"><div class="account-avatar">${esc((session.user.name||session.user.email||'G')[0].toUpperCase())}</div><div><strong>${session.user.kind==='guest'?L('Guest paper workspace','Gjestearbeidsområde'):esc(session.user.email)}</strong><div class="small muted">${L('Private server-owned records','Private serverlagrede registreringer')}</div></div></div><p>${session.user.kind==='guest'?guestDisclosure():L('Your account has its own watchlist, settings, strategies, alerts and paper ledger. Signing out does not publish or delete your records.','Kontoen har egen overvåkingsliste, innstillinger, strategier, varsler og papirhovedbok. Utlogging publiserer eller sletter ikke registreringene.')}</p><div class="form-actions">${btn(session.user.kind==='guest'?(session.capabilities?.signupEnabled===true?L('Sign in / create account','Logg inn / opprett konto'):L('Sign in','Logg inn')):L('Account options','Kontoalternativer'),'account','user')}${btn(L('Alerts','Varsler'),'alerts','bell')}</div></section><section class="panel page-panel"><h2>${L('Data integrations','Datatilkoblinger')}</h2><p>${L('This workspace uses fixed fictional sample data. No live quote, news, calendar or AI service is currently implied. Provider requests require explicit configuration, credentials and display entitlements.','Arbeidsområdet bruker faste fiktive eksempeldata. Ingen løpende kurs-, nyhets-, kalender- eller KI-tjeneste er underforstått. Leverandørforespørsler krever eksplisitt oppsett, tilkoblingsnøkler og visningsrettigheter.')}</p><div class="form-actions">${btn(L('Check integration status','Kontroller tilkoblingsstatus'),'integrations','refresh')}${btn(L('Read sample provenance','Les om eksempelkilden'),'data-info','book')}</div></section><section class="panel page-panel"><h2>${L('Real-money brokerage','Megler for ekte penger')}</h2><div class="badge amber">${L('Disabled','Deaktivert')}</div><p class="mt-10">${L('No brokerage orders can be sent from this release. A separately reviewed integration, supported credentials and explicit authorization are required before real execution.','Ingen meglerordrer kan sendes fra denne versjonen. En separat gjennomgått tilkobling, støttede innloggingsopplysninger og uttrykkelig tillatelse kreves før faktisk handel.')}</p><button disabled class="mt-12">${L('Live connection unavailable','Direktetilkobling utilgjengelig')}</button></section></div>`;}
function guestDisclosure(){return L('Guest access lasts one day in this browser; server records expire after seven days. Clearing or losing the session cookie loses access. Guest records do not transfer to an account. A new guest starts with virtual USD 100,000.','Gjestetilgangen varer ett døgn i nettleseren; serverregistreringer utløper etter sju dager. Sletting eller tap av øktinformasjonskapselen fjerner tilgangen. Gjesteregistreringer overføres ikke til en konto. En ny gjest starter med virtuelle USD 100 000.')+(session.storage?.expiresAt?' '+L('Expiry','Utløp')+': '+date(session.storage.expiresAt)+'.':'');}
function alertsPage(){return `<section class="panel page-panel"><h2>${L('Sample price alerts','Varsler for eksempelkurser')}</h2><div class="table-wrap"><table class="view-table"><thead><tr><th>${L('Instrument','Instrument')}</th><th>${L('Condition','Vilkår')}</th><th>${L('Status','Status')}</th><th>${L('Created','Opprettet')}</th><th></th></tr></thead><tbody>${(state.alerts||[]).map(a=>`<tr><td>${esc(a.symbol)}</td><td>${a.direction==='above'?L('At or above','Ved eller over'):L('At or below','Ved eller under')} ${money(a.priceMinor)}</td><td class="${a.status==='triggered'?'positive':'muted'}">${stateName(a.status)}</td><td>${date(a.createdAt)}</td><td>${btn(L('Remove','Fjern'),'alert-remove','trash','danger',`data-id="${esc(a.id)}"`)}</td></tr>`).join('')||`<tr><td colspan="5" class="list-empty">${L('Create an alert for a known sample symbol. It is evaluated on the server as replay advances.','Opprett et varsel for et kjent eksempelsymbol. Det vurderes på serveren mens avspillingen fortsetter.')}</td></tr>`}</tbody></table></div><div class="form-actions">${btn(L('Create price alert','Opprett prisvarsel'),'alert','plus','primary')}${btn(L('Notifications','Varslinger'),'notifications','bell')}</div></section>`;}
function showDialog(title,body,kind='info'){activeDialog=kind;modal.innerHTML=`<div class="modal-heading"><h2 id="modal-title">${title}</h2>${iconButton(L('Close dialog','Lukk vinduet'),'close-modal','x')}</div><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal();modal.querySelector('.modal-body input:not([type=hidden]),.modal-body select,.modal-body button')?.focus();}
function closeDialog(){modal.close();activeDialog=null;}
function openDataInfo(){showDialog(L('Sample data & paper execution','Eksempeldata og papirutførelse'),`<div class="badge amber">${L('FIXED FICTIONAL SAMPLE · PAPER ONLY','FAST FIKTIVT EKSEMPEL · KUN PAPIRHANDEL')}</div><p class="mt-14">${L('All quotes, candles, news and calendar events are original fictional fixtures for 13 and 16 November 2026. They are not real historical prices or current coverage. Ticker names identify the example instruments only.','Alle kurser, datapunkter, nyheter og kalenderhendelser er originale fiktive eksempler for 13. og 16. november 2026. De er ikke faktiske historiske kurser eller aktuelle nyheter. Symbolnavn identifiserer kun eksempelinstrumentene.')}</p><p>${L('Prices are USD integer cents. Sessions follow 09:30–16:00 America/New_York. Candle timestamps are interval-close times. No overnight bars are invented; higher timeframes require complete known intervals and indicators require warm-up.','Kurser er heltall i amerikanske cent. Økter følger 09:30–16:00 America/New_York. Datapunkter er tidsstemplet ved intervallslutt. Ingen nattlige datapunkter diktes opp; lengre intervaller krever fullførte kjente perioder og indikatorer krever datagrunnlag.')}</p><p>${L('Paper market orders become eligible on the next known bar, with configured adverse slippage and fees. Limits and stops use a conservative model; a stop wins if stop and target are both touched. There is no real liquidity, order queue or partial-fill simulation.','Papirmarkedsordrer kan utføres ved neste kjente datapunkt med valgte ugunstige prisglidninger og gebyrer. Limit og stopp bruker en forsiktig modell; stopp gjelder hvis både stopp og mål treffes. Modellen har ingen faktisk likviditet, ordrekø eller delvis utførelse.')}</p><p>${session.user.kind==='guest'?guestDisclosure():L('Your account records are stored privately on the server.','Kontoregistreringene dine lagres privat på serveren.')}</p><div class="callout warning">${L('In-tab replay pauses on reconnect or when this tab is hidden. Real-money brokerage execution is disabled. Historical report performance is separate.','Avspillingen i fanen pauses ved ny tilkobling eller når fanen skjules. Handel med ekte penger er deaktivert. Historiske rapportresultater er adskilt.')}</div><div class="form-actions">${btn(L('Integration status','Tilkoblingsstatus'),'integrations','world')}${btn(L('Continue to workspace','Fortsett til arbeidsområdet'),'close-modal','','primary')}</div>`);}
function openSearch(){showDialog(L('Search markets & published news','Søk i markeder og publiserte nyheter'),`<label class="field"><span>${L('Symbol, company or headline','Symbol, selskap eller overskrift')}</span><input id="symbol-search" type="search" placeholder="${L('Search the known sample snapshot','Søk i det kjente eksempeldatasettet')}" autocomplete="off"></label><div id="search-results" class="search-results"></div>`,'search');const input=modal.querySelector('#symbol-search');const display=()=>{const q=input.value.toLowerCase().trim(),items=(state.catalog||[]).filter(item=>(item.symbol+' '+item.name).toLowerCase().includes(q));modal.querySelector('#search-results').innerHTML=items.map(item=>`<div class="market-row search-market-row"><button data-action="search-select" data-symbol="${esc(item.symbol)}"><span class="watch-symbol">${glyph(item.symbol)}${esc(item.symbol)}</span><span class="small muted">${esc(item.name)}</span></button>${iconButton(state.watchlist.includes(item.symbol)?L('Remove from watchlist','Fjern fra listen'):L('Add to watchlist','Legg til i listen'),state.watchlist.includes(item.symbol)?'search-remove':'search-add',state.watchlist.includes(item.symbol)?'check':'plus',`data-symbol="${esc(item.symbol)}"`)}</div>`).join('')+(q?(state.news||[]).filter(n=>(n.title+' '+n.symbols.join(' ')).toLowerCase().includes(q)).map(n=>`<button data-action="search-news" data-id="${esc(n.id)}"><span>${esc(n.title)}<small class="muted"> · ${L('Fictional sample news','Fiktiv eksempelnyhet')}</small></span>${icon('arrow-right')}</button>`).join(''):'');};input.addEventListener('input',display);display();input.focus();}
let orderDraft=null,orderRequestId=null;
function openOrder({symbol=selected(),side='buy',quantity=10,draft=null}={}){const d=draft||{symbol,side,quantity,orderType:'market'};orderDraft=d;orderRequestId=null;showDialog(L('New paper order','Ny papirordre'),`<div class="badge">${L('PAPER SIMULATION · USD','PAPIRSIMULERING · USD')}</div><form id="order-form"><div class="form-grid"><label class="field"><span>${L('Instrument','Instrument')}</span><select name="symbol">${state.catalog.map(c=>`<option value="${esc(c.symbol)}" ${c.symbol===d.symbol?'selected':''}>${esc(c.symbol)} · ${esc(c.name)}</option>`).join('')}</select></label><label class="field"><span>${L('Side','Retning')}</span><select name="side"><option value="buy" ${d.side==='buy'?'selected':''}>${L('Buy','Kjøp')}</option><option value="sell" ${d.side==='sell'?'selected':''}>${L('Sell held shares','Selg eide aksjer')}</option></select></label>${field(L('Whole shares','Helt antall aksjer'),'quantity',d.quantity,'number','min="1" max="100000" step="1" required')}<label class="field"><span>${L('Order type','Ordretype')}</span><select name="orderType">${['market','limit','stop'].map(t=>`<option value="${t}" ${d.orderType===t?'selected':''}>${typeName(t)}</option>`).join('')}</select></label><div class="field full" id="order-price-field" ${d.orderType==='market'?'hidden':''}><label class="field"><span>${L('Trigger / limit price (USD)','Utløserkurs / limitkurs (USD)')}</span><input name="price" type="number" min="0.01" max="1000000" step="0.01" value="${esc(d.price||(state.markets[d.symbol]?.quote.priceMinor/100).toFixed(2))}"></label></div>${field(L('Optional stop loss (USD)','Valgfri stopptapskurs (USD)'),'stopLoss',d.stopLoss||'','number','min="0.01" step="0.01"')}${field(L('Optional profit target (USD)','Valgfri gevinstmålkurs (USD)'),'takeProfit',d.takeProfit||'','number','min="0.01" step="0.01"')}</div><p class="form-note">${L('Reference sample quote','Referansekurs i eksemplet')}: <strong id="order-quote">${money(state.markets[d.symbol]?.quote.priceMinor)}</strong>. ${L('Available virtual cash','Tilgjengelige virtuelle kontanter')}: ${money(state.account.availableCashMinor??state.account.cashMinor)}. ${L('Orders fill only after replay advances. Protective exits apply to buys.','Ordrer utføres først når avspillingen fortsetter. Beskyttelsesordrer gjelder kjøp.')}</p><div class="form-actions"><button class="primary" type="submit">${L('Review paper order','Se gjennom papirordren')}</button>${btn(L('Cancel','Avbryt'),'close-modal')}</div><div class="inline-error" data-form-error role="alert"></div></form>`,'order');const form=modal.querySelector('#order-form');form.elements.orderType.addEventListener('change',()=>{modal.querySelector('#order-price-field').hidden=form.elements.orderType.value==='market';form.elements.price.required=form.elements.orderType.value!=='market';});form.elements.symbol.addEventListener('change',()=>{modal.querySelector('#order-quote').textContent=money(state.markets[form.elements.symbol.value]?.quote.priceMinor);});form.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(form);orderDraft=Object.fromEntries(data);reviewOrder();});}
function reviewOrder(){const d=orderDraft,price=Number(d.price),reference=state.markets[d.symbol]?.quote.priceMinor||0,quantity=Number(d.quantity);const payload={type:'order_submit',confirmed:true,symbol:d.symbol,side:d.side,orderType:d.orderType,quantity};if(d.orderType==='limit')payload.limitPriceMinor=Math.round(price*100);if(d.orderType==='stop')payload.stopPriceMinor=Math.round(price*100);if(d.stopLoss)payload.stopLossMinor=Math.round(Number(d.stopLoss)*100);if(d.takeProfit)payload.takeProfitMinor=Math.round(Number(d.takeProfit)*100);orderRequestId=crypto.randomUUID();const estimatedPrice=d.orderType==='market'?reference:Math.round(price*100),estimatedNotional=quantity*estimatedPrice;showDialog(L('Confirm simulated order','Bekreft simulert ordre'),`<div class="badge amber">${L('PAPER ORDER · NO REAL MONEY','PAPIRORDRE · INGEN EKTE PENGER')}</div><p class="mt-13"><strong>${sideName(d.side)} ${quantity} ${esc(d.symbol)}</strong> · ${typeName(d.orderType)}</p><div class="confirm-total">${money(estimatedNotional)}</div><p>${L('Estimated notional at reference / limit price; final execution may differ.','Anslått beløp ved referanse- eller limitkurs; endelig utførelse kan avvike.')} ${L('Fee per fill','Gebyr per utførelse')}: ${money(state.risk.feePerOrderMinor)} · ${L('Slippage','Prisglidning')}: ${state.risk.slippageBps} ${L('basis points','basispunkter')}.</p><div class="callout">${L('The server checks available funds, whole shares, exposure and daily limits. A confirmed order may be rejected now or at its next eligible sample bar.','Serveren kontrollerer tilgjengelige midler, hele aksjer, eksponering og daglige grenser. En bekreftet ordre kan avvises nå eller ved neste aktuelle eksempeldatapunkt.')}</div><form id="confirm-order-form"><div class="form-actions"><button type="submit" class="primary">${L('Confirm paper order','Bekreft papirordre')}</button>${btn(L('Edit','Rediger'),'order-edit')}${btn(L('Cancel','Avbryt'),'close-modal')}</div><div class="inline-error" data-form-error role="alert"></div></form>`,'order-confirm');const form=modal.querySelector('form');form.addEventListener('submit',async e=>{e.preventDefault();const submit=form.querySelector('[type=submit]');submit.disabled=true;try{const result=await command(payload,{requestId:orderRequestId});if(result.status==='rejected'){showOrderRejection(result);return;}closeDialog();toast(L('Paper order saved. Advance replay for its next eligible fill.','Papirordren er lagret. Fortsett avspillingen til neste aktuelle utførelse.'));go('trade');}catch(error){form.querySelector('[data-form-error]').textContent=errorText(error);submit.disabled=false;}});}
function riskName(check){return({cash:L('Available cash, fees & reservations','Tilgjengelige kontanter, gebyrer og reservasjoner'),exposure:L('Maximum portfolio exposure','Maksimal porteføljeeksponering'),position:L('Maximum instrument exposure','Maksimal instrumenteksponering'),'daily-loss':L('Daily paper loss limit','Daglig tapsgrense for papirhandel'),'trade-limit':L('Daily entry limit','Daglig inngangsgrense'),holdings:L('Available whole shares','Tilgjengelige hele aksjer'),'sell-fee':L('Sale covers execution fee','Salget dekker utførelsesgebyret'),'one-entry':L('No existing entry or pending buy','Ingen eksisterende inngang eller ventende kjøp')})[check.id]||L(check.label,L('Risk check','Risikokontroll'));}
function riskValue(value,id){if(value===null||value===undefined)return'—';if(typeof value==='boolean')return value?L('Yes','Ja'):L('No','Nei');return ['trade-limit','holdings','one-entry'].includes(id)?esc(value):money(value);}
function riskEvidence(checks){return (checks||[]).map(c=>`<div class="evidence-row">${checkIcon(c.passed)}<div>${esc(riskName(c))}<small>${L('Actual','Faktisk')}: ${riskValue(c.actual,c.id)} · ${L('Limit','Grense')}: ${riskValue(c.limit,c.id)}</small></div></div>`).join('');}
function showOrderRejection(result){showDialog(L('Paper order rejected','Papirordren ble avvist'),`<div class="callout error">${L('The server saved the rejected order without creating a fill. Review the failed checks before submitting a new order.','Serveren lagret den avviste ordren uten å utføre en handel. Se vilkårene som ikke ble oppfylt før du sender en ny ordre.')}</div>${riskEvidence(result.riskChecks)}<div class="form-actions">${btn(L('View orders','Se ordrer'),'close-to-trade','list','primary')}${btn(L('Risk settings','Risikoinnstillinger'),'close-to-risk','settings')}</div>`,'rejection');}
function openSignal(id){const s=state.signals.find(s=>s.id===id);if(!s)return;showDialog(`${L('Signal evidence','Signalgrunnlag')} · ${esc(s.symbol)}`,`<div class="badge ${s.decision==='blocked'?'amber':''}">${stateName(s.decision)} · ${s.conditionsMet}/${s.conditionsTotal} ${L('conditions met','vilkår oppfylt')}</div><p class="mt-12">${date(s.time)} · ${esc(zone())} · ${esc(s.strategyVersion)} · ${L('1-minute rule','1-minuttsregel')}</p><dl class="detail-list">${[[L('Reference price','Referansekurs'),money(s.priceMinor)],[L('Proposed shares','Foreslått antall'),s.quantity],[L('Estimated entry','Anslått inngang'),money(s.estimatedEntryMinor)],[L('Estimated fee','Anslått gebyr'),money(s.estimatedFeeMinor)],[L('Stop loss','Stopptap'),s.stopLossMinor?money(s.stopLossMinor):'—'],[L('Profit target','Gevinstmål'),s.takeProfitMinor?money(s.takeProfitMinor):'—']].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl><h3>${L('Conditions at this data snapshot','Vilkår ved dette datagrunnlaget')}</h3>${s.conditions.map(c=>`<div class="evidence-row">${checkIcon(c.met)}<div>${esc(conditionName(c))}${c.enabled===false?` <span class="muted">(${L('disabled','deaktivert')})</span>`:''}<small>${L('Observed','Observert')}: ${conditionValue(c.actual,c.id)} · ${L('Required','Krav')}: ${conditionValue(c.expected,c.id)}</small></div></div>`).join('')}<h3 class="mt-17">${L('Risk checks','Risikokontroll')}</h3>${riskEvidence(s.riskChecks)||`<p class="help">${L('No order proposed; risk checks are not applicable.','Ingen ordre foreslått; risikokontroll er ikke relevant.')}</p>`}<p class="form-note">${L('Data as of','Data per')}: ${date(s.dataSnapshot?.asOf||s.time)} · ${L('Replay cursor','Avspillingspunkt')}: ${s.dataSnapshot?.cursor??'—'} · ${L('Audit reference','Loggreferanse')}: ${esc(s.id)}${s.orderId?' · '+L('Order','Ordre')+': '+esc(s.orderId):''}. ${L('Agreement is not a probability of profit.','Enighet er ikke en sannsynlighet for gevinst.')}</p><div class="form-actions">${btn(L('Show exact time on chart','Vis nøyaktig tidspunkt i grafen'),'signal-chart','chart-candle','primary',`data-id="${esc(s.id)}"`)}${btn(L('Close','Lukk'),'close-modal')}</div>`,'signal');}
function openAlert(){showDialog(L('Create sample price alert','Opprett varsel for eksempelkurs'),`<p>${L('Evaluated against known sample closing prices as replay advances. In-app delivery only.','Vurderes mot kjente eksempelsluttkurser når avspillingen fortsetter. Varsling kun i appen.')}</p><form id="alert-form"><div class="form-grid"><label class="field"><span>${L('Instrument','Instrument')}</span><select name="symbol">${state.catalog.map(c=>`<option ${c.symbol===selected()?'selected':''}>${esc(c.symbol)}</option>`).join('')}</select></label><label class="field"><span>${L('Condition','Vilkår')}</span><select name="direction"><option value="above">${L('At or above','Ved eller over')}</option><option value="below">${L('At or below','Ved eller under')}</option></select></label>${field(L('Price (USD)','Kurs (USD)'),'price',(market().quote.priceMinor/100).toFixed(2),'number','min="0.01" max="1000000" step="0.01" required')}</div><div class="form-actions"><button type="submit" class="primary">${L('Save alert','Lagre varsel')}</button>${btn(L('All alerts','Alle varsler'),'close-to-alerts')}</div><div class="inline-error" data-form-error role="alert"></div></form>`,'alert');const form=modal.querySelector('form');form.addEventListener('submit',e=>submitForm(e,async data=>{await command({type:'alert_add',symbol:data.symbol,direction:data.direction,priceMinor:Math.round(Number(data.price)*100)});closeDialog();toast(L('Price alert saved.','Prisvarselet er lagret.'));}));}
function notificationTitle(n){return ({'Fictional replay ready':L('Fictional replay ready','Fiktiv avspilling klar'),'Paper order pending':L('Paper order pending','Papirordre venter'),'Paper order filled':L('Paper order filled','Papirordre utført'),'Paper order rejected':L('Paper order rejected','Papirordre avvist'),'Paper order rejected at fill':L('Paper order rejected at fill','Papirordre avvist ved utførelse'),'Strategy blocked by risk controls':L('Strategy blocked by risk controls','Strategien ble blokkert av risikokontroll'),'Sample price alert':L('Sample price alert','Varsel for eksempelkurs')})[n.title]||esc(n.title);}
function notificationMessage(n){if(lang==='en')return n.message;return n.title==='Fictional replay ready'?'Papirkonto med virtuelle USD 100 000. Avspillingen kjører kun mens du fortsetter i denne fanen. Ingen megler er tilkoblet.':n.title==='Paper order pending'?n.message.replace('buy ','Kjøp ').replace('sell ','Selg ').replace('; eligible from the next replay bar.','; aktuell for utførelse ved neste avspillingspunkt.'):n.title==='Paper order filled'?n.message.replace('buy ','Kjøp ').replace('sell ','Selg ').replace(' at USD ',' til USD ').replace('; fee USD ','; gebyr USD '):n.title==='Sample price alert'?n.message.replace(' closed above USD ',' sluttet over USD ').replace(' closed below USD ',' sluttet under USD '):L(n.message,'Se ordren eller signalet for risikogrunnlaget.');}
function signupControl(mode){return session.capabilities?.signupEnabled===true?btn(L('Create account','Opprett konto'),'auth-signup','',mode==='signup'?'selected':''):`<button type="button" disabled>${L('Account creation closed','Kontooppretting stengt')}</button>`;}
function openNotifications(){showDialog(L('In-app notifications','Varslinger i appen'),`<div class="form-actions compact-actions">${btn(L('Mark all read','Merk alle som lest'),'notifications-all','check')}${btn(L('Manage price alerts','Administrer prisvarsler'),'close-to-alerts','bell')}</div><div class="notice-list">${[...(state.notifications||[])].reverse().map(n=>`<button data-action="notice-read" data-id="${esc(n.id)}" class="${n.read?'':'unread'}"><strong>${n.read?'':`<span class="dot positive"></span> `}${notificationTitle(n)}</strong><small>${esc(notificationMessage(n))}</small><small>${date(n.time)} · ${n.read?L('Read','Lest'):L('Unread','Ulest')}</small></button>`).join('')||`<p>${L('No notifications yet.','Ingen varslinger ennå.')}</p>`}</div>`,'notifications');}
function openAccount(mode='login'){if(mode==='signup'&&session.capabilities?.signupEnabled!==true)mode='login';if(session.user.kind==='user'&&!sessionExpired){showDialog(L('Your private account','Din private konto'),`<div class="account-identity"><div class="account-avatar">${icon('user')}</div><div><strong>${esc(session.user.name||session.user.email)}</strong><div class="small muted">${esc(session.user.email)}</div></div></div><p>${L('Your paper records are isolated on the server. Sign in again to restore this account. Email verification and password recovery are not connected in this release.','Papirregistreringene er adskilt på serveren. Logg inn igjen for å åpne kontoen. E-postbekreftelse og passordgjenoppretting er ikke tilkoblet i denne versjonen.')}</p><div class="form-actions">${btn(L('Sign out','Logg ut'),'logout','logout','danger')}${btn(L('Close','Lukk'),'close-modal')}</div>`,'account');return;}showDialog(mode==='signup'?L('Create a paper account','Opprett en papirkonto'):L('Sign in to paper trading','Logg inn på papirhandel'),`<div class="auth-tabs">${btn(L('Sign in','Logg inn'),'auth-login','',mode==='login'?'selected':'')}${signupControl(mode)}</div><p>${L('Your guest sandbox is separate. Signing in or creating an account opens that account’s records; guest trades do not transfer. Export guest history first if you want to keep it.','Gjestearbeidsområdet er adskilt. Innlogging eller oppretting åpner kontoens registreringer; gjestehandler overføres ikke. Eksporter gjestehistorikken først hvis du vil beholde den.')}</p>${session.capabilities?.signupEnabled===true?'':`<div class="callout warning">${L('Public account creation is not open in this release. Guest access and sign-in remain available.','Offentlig kontooppretting er ikke åpen i denne versjonen. Gjestetilgang og innlogging er tilgjengelig.')}</div>`}<form id="auth-form">${mode==='signup'?field(L('Name (optional)','Navn (valgfritt)'),'name','','text','autocomplete="name" maxlength="100"'):''}${field(L('Email','E-post'),'email','','email','autocomplete="email" required maxlength="254"')}${field(L('Password','Passord'),'password','','password',`autocomplete="${mode==='signup'?'new-password':'current-password'}" minlength="12" maxlength="256" required`,L('At least 12 characters. Email verification and password recovery are not connected.','Minst 12 tegn. E-postbekreftelse og passordgjenoppretting er ikke tilkoblet.'))}<div class="form-actions"><button type="submit" class="primary">${mode==='signup'?L('Create account','Opprett konto'):L('Sign in','Logg inn')}</button>${btn(L('Continue as guest','Fortsett som gjest'),'close-modal')}</div><div class="inline-error" data-form-error role="alert"></div></form><p class="form-note">${guestDisclosure()}</p>`,'auth');modal.querySelector('form').addEventListener('submit',e=>submitForm(e,async data=>{autoAdvance=false;const result=await api(mode,{method:'POST',body:data});session=result;sessionExpired=false;state=result.state;if(['starting','running'].includes(state.engine.status))await command({type:'engine_pause'},{repaint:false});if(state.settings.language!==lang)await command({type:'settings_update',settings:{language:lang}},{repaint:false});closeDialog();render();toast(L('Private paper account opened.','Den private papirkontoen er åpnet.'));}));}
async function openIntegrations(){showDialog(L('Integration status','Tilkoblingsstatus'),`<p>${L('Checking server configuration…','Kontrollerer serveroppsettet…')}</p>`,'integrations');try{const result=await api('integrations');session.integrations=result.integrations;const titles={market:L('Market data','Markedsdata'),news:L('News provider','Nyhetsleverandør'),calendar:L('Economic calendar','Økonomisk kalender'),brokerage:L('Real-money brokerage','Megler for ekte penger'),ai:L('AI explanations','KI-forklaringer')};if(activeDialog!=='integrations')return;showDialog(L('Integration status','Tilkoblingsstatus'),Object.entries(result.integrations).map(([key,status])=>`<div class="evidence-row">${icon(status.available?'circle-check':'info-circle')}<div><strong>${titles[key]||esc(key)}</strong> <span class="badge ${status.available?'':'amber'}">${status.available?L('Configured','Konfigurert'):L('Unavailable','Utilgjengelig')}</span><small>${status.available?L('Configured by the owner; entitlement and response availability still require verification.','Konfigurert av eieren; rettigheter og svartilgjengelighet må fortsatt kontrolleres.'):key==='brokerage'?L('Unconditionally disabled in this release.','Ubetinget deaktivert i denne versjonen.'):key==='ai'?L('No summarization service is connected. Rule evidence remains available.','Ingen oppsummeringstjeneste er tilkoblet. Regelgrunnlaget er tilgjengelig.'):L('Requires server credentials, written commercial-display rights and an enabled capability.','Krever tilkoblingsnøkler på serveren, skriftlige rettigheter for kommersiell visning og aktivert funksjon.')}</small></div></div>`).join('')+`<div class="callout">${L('This session remains explicitly in fictional sample mode. A configured provider never silently replaces the paper engine’s sample prices.','Denne økten forblir uttrykkelig i fiktiv eksempelmodus. En konfigurert leverandør erstatter aldri papirmotorens eksempelkurser uten beskjed.')}</div>`,'integrations');}catch(error){if(activeDialog==='integrations')showDialog(L('Integration status unavailable','Tilkoblingsstatus utilgjengelig'),`<p>${esc(errorText(error))}</p>`);}}
async function submitForm(event,work){event.preventDefault();const form=event.currentTarget,submit=form.querySelector('[type=submit]'),errorNode=form.querySelector('[data-form-error]');if(submit.disabled)return;submit.disabled=true;errorNode.textContent='';try{await work(Object.fromEntries(new FormData(form)));}catch(error){errorNode.textContent=errorText(error);}finally{if(submit.isConnected)submit.disabled=false;}}
function bindForms(){app.querySelector('#market-search')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();app.querySelectorAll('[data-market-text]').forEach(row=>row.hidden=!row.dataset.marketText.includes(q));});app.querySelector('#strategy-form')?.addEventListener('submit',e=>submitForm(e,async d=>{const f=e.currentTarget;await command({type:'strategy_update',strategy:{fastPeriod:Number(d.fastPeriod),slowPeriod:Number(d.slowPeriod),quantity:Number(d.quantity),volumeMultiplier:Number(d.volumeMultiplier),stopLossBps:Math.round(Number(d.stopLossPercent)*100),takeProfitBps:Math.round(Number(d.takeProfitPercent)*100),useVwap:f.elements.useVwap.checked,useVolume:f.elements.useVolume.checked,autoTrade:f.elements.autoTrade.checked}},{message:L('Strategy saved on the server.','Strategien er lagret på serveren.')});}));app.querySelector('#risk-form')?.addEventListener('submit',e=>submitForm(e,d=>command({type:'settings_update',risk:{maxExposureBps:Math.round(Number(d.maxExposurePercent)*100),maxPositionBps:Math.round(Number(d.maxPositionPercent)*100),maxDailyLossMinor:Math.round(Number(d.maxDailyLoss)*100),maxTradesPerDay:Number(d.maxTradesPerDay),feePerOrderMinor:Math.round(Number(d.fee)*100),slippageBps:Number(d.slippageBps)}},{message:L('Risk limits saved on the server.','Risikogrensene er lagret på serveren.')})));app.querySelector('#settings-form')?.addEventListener('submit',e=>submitForm(e,async d=>{await command({type:'settings_update',settings:d},{repaint:false});lang=d.language;history.replaceState(null,'',`/${lang}/terminal/${location.hash}`);render();toast(L('Preferences saved.','Innstillingene er lagret.'));}));app.querySelectorAll('[data-indicator]').forEach(input=>input.addEventListener('change',()=>commandUI({type:'settings_update',settings:{indicators:{...state.settings.indicators,[input.dataset.indicator]:input.checked}}})));}
async function selectSymbol(symbol,{close=false,showChart=true}={}){marker=null;await commandUI({type:'select_symbol',symbol});if(close)closeDialog();if(showChart)go('overview');}
async function waitForIdle(){while(busy)await new Promise(resolve=>setTimeout(resolve,40));}
async function pauseReplay(){autoAdvance=false;await waitForIdle();if(state&&['running','starting'].includes(state.engine.status))await commandUI({type:'engine_pause'});}
async function exportHistory(){try{const response=await fetch('/.netlify/functions/terminal?action=export',{credentials:'same-origin'});if(!response.ok){const data=await response.json();throw data.error;}const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`Nortivo-paper-history-${new Date().toISOString().slice(0,10)}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(L('Paper history exported.','Papirhistorikken er eksportert.'));}catch(error){toast(errorText(error));}}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action;try{if(['overview','markets','trade','bots','strategy','research','news','calendar','analytics','reports','settings','alerts'].includes(action)){if(modal.open)closeDialog();go(action);return;}switch(action){case'close-modal':closeDialog();break;case'search':openSearch();break;case'select-symbol':case'search-select':await selectSymbol(el.dataset.symbol,{close:action==='search-select'});break;case'watchlist-add':case'watchlist-remove':await commandUI({type:action==='watchlist-add'?'watchlist_add':'watchlist_remove',symbol:el.dataset.symbol},{message:L('Watchlist saved.','Overvåkingslisten er lagret.')});break;case'search-add':case'search-remove':await commandUI({type:action==='search-add'?'watchlist_add':'watchlist_remove',symbol:el.dataset.symbol});openSearch();break;case'watchlist-sort':{const choices=['manual','symbol','change'],next=choices[(choices.indexOf(state.settings.watchlistSort)+1)%choices.length];await commandUI({type:'watchlist_sort',sort:next},{message:L('Watchlist order: ','Listerekkefølge: ')+({manual:L('added order','lagt til'),symbol:L('symbol A–Z','symbol A–Å'),change:L('price change','kursendring')})[next]});break;}case'watchlist-tab':toast(L('Your server-saved watchlist is selected.','Den serverlagrede overvåkingslisten er valgt.'));break;case'timeframe':await commandUI({type:'settings_update',settings:{timeframe:el.dataset.value}});break;case'chart-fullscreen':{const panel=app.querySelector('#chart-panel');panel.classList.toggle('chart-expanded');document.body.classList.toggle('chart-open',panel.classList.contains('chart-expanded'));el.setAttribute('aria-label',panel.classList.contains('chart-expanded')?L('Close expanded chart','Lukk utvidet graf'):L('Expand chart','Utvid grafen'));chart.draw();break;}case'chart-data':app.querySelector('.chart-data').open=!app.querySelector('.chart-data').open;break;case'order':openOrder();break;case'order-sell':openOrder({symbol:el.dataset.symbol,side:'sell',quantity:Number(el.dataset.quantity)});break;case'order-edit':openOrder({draft:orderDraft});break;case'order-cancel':await commandUI({type:'order_cancel',orderId:el.dataset.id},{message:L('Pending order cancelled.','Den ventende ordren er kansellert.')});break;case'replay-step':case'replay-ten':case'replay-thirty':await commandUI({type:'replay_advance',steps:action==='replay-step'?1:action==='replay-ten'?10:30});break;case'engine-start':await command({type:'engine_start'});autoAdvance=['starting','running'].includes(state.engine.status);toast(L('In-tab replay started. One sample bar every 4 seconds.','Avspillingen i fanen er startet. Ett eksempelpunkt hvert 4. sekund.'));break;case'engine-pause':await pauseReplay();toast(L('In-tab replay paused. No new strategy evaluations will run.','Avspillingen i fanen er pauset. Ingen nye strategivurderinger kjøres.'));break;case'engine-stop':autoAdvance=false;await waitForIdle();await commandUI({type:'engine_stop'},{message:L('Engine stopped. Manual pending orders and holdings are retained.','Motoren er stoppet. Manuelle ventende ordrer og posisjoner er beholdt.')});break;case'news-filter':newsFilter=el.dataset.value;render();break;case'news-expand':expandedNews.has(el.dataset.id)?expandedNews.delete(el.dataset.id):expandedNews.add(el.dataset.id);render();break;case'search-news':expandedNews.add(el.dataset.id);closeDialog();go('news');break;case'news-chart':{const n=state.news.find(n=>n.id===el.dataset.id);if(n?.symbols?.[0])await command({type:'select_symbol',symbol:n.symbols[0]},{repaint:false});marker={time:n.publishedAt,label:L('Published sample news','Publisert eksempelnyhet')};closeDialog();go('overview');toast(L('Publication time highlighted. Timing does not establish causation.','Publiseringstid er markert. Tidssammenfall viser ikke årsak.'));break;}case'news-source':{const n=state.news.find(n=>n.id===el.dataset.id);showDialog(L('Fictional sample source','Fiktiv eksempelkilde'),`<p>${esc(n.source)} · ${date(n.publishedAt)}</p><p>${L('This original fixture has no external article. It is not real reporting, a machine summary, an impact estimate or an instruction to trade.','Dette originale eksemplet har ingen ekstern artikkel. Det er ikke faktisk journalistikk, en maskinoppsummering, et konsekvensanslag eller en handelsinstruksjon.')}</p>`);break;}case'signal-detail':openSignal(el.dataset.id);break;case'signal-chart':{const s=state.signals.find(s=>s.id===el.dataset.id);await command({type:'select_symbol',symbol:s.symbol},{repaint:false});marker={time:s.time,label:L('Rule evaluation','Regelvurdering')};closeDialog();go('overview');break;}case'risk-settings':go('strategy');setTimeout(()=>app.querySelector('#risk-form-panel')?.scrollIntoView({block:'center'}),0);break;case'alert':openAlert();break;case'alert-remove':await commandUI({type:'alert_remove',alertId:el.dataset.id},{message:L('Alert removed.','Varselet er fjernet.')});break;case'notifications':openNotifications();break;case'notice-read':await commandUI({type:'notifications_read',ids:[el.dataset.id]});openNotifications();break;case'notifications-all':await commandUI({type:'notifications_read'});openNotifications();break;case'account':openAccount();break;case'auth-login':openAccount('login');break;case'auth-signup':openAccount('signup');break;case'logout':autoAdvance=false;await pauseReplay();await api('logout',{method:'POST',body:{}});closeDialog();session=await api('guest',{method:'POST',body:{}});state=session.state;marker=null;render();toast(L('Signed out. A separate new guest workspace is open.','Logget ut. Et separat nytt gjestearbeidsområde er åpnet.'));break;case'export':await exportHistory();break;case'data-info':openDataInfo();break;case'integrations':await openIntegrations();break;case'trend-info':showDialog(L('A disclosed rule-based trend','En tydelig regelbasert trend'),`<p>${L('The breadth score is the share of the five fixed sample instruments above their previous sample session close at the known replay timestamp. It is not news sentiment, an AI forecast, a confidence score or a survey.','Breddetallet er andelen av de fem faste eksempelinstrumentene som er over forrige eksempeløkts sluttkurs ved det kjente avspillingstidspunktet. Det er ikke nyhetsstemning, en KI-prognose, en sikkerhetsprosent eller en undersøkelse.')}</p><p>${L('Source: fictional sample bars only.','Kilde: kun fiktive eksempeldatapunkter.')}</p>`);break;case'close-to-trade':closeDialog();go('trade');break;case'close-to-risk':closeDialog();go('strategy');break;case'close-to-alerts':closeDialog();go('alerts');break;case'retry-start':start();break;}}catch(error){toast(errorText(error));}});
window.addEventListener('hashchange',()=>{document.body.classList.remove('chart-open');render();});
document.addEventListener('keydown',event=>{if(productActive)return;if(event.key==='Escape'&&document.body.classList.contains('chart-open')){app.querySelector('.chart-expanded')?.classList.remove('chart-expanded');document.body.classList.remove('chart-open');chart?.draw();}if(event.key==='/'&&!modal.open&&!['INPUT','TEXTAREA','SELECT'].includes(event.target.tagName)){event.preventDefault();openSearch();}});
modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog();}});
modal.addEventListener('close',()=>{activeDialog=null;});
setInterval(async()=>{if(!autoAdvance||busy||document.hidden||!state||!['starting','running'].includes(state.engine.status))return;try{const editing=!!app.querySelector('form')?.contains(document.activeElement);await command({type:'replay_advance',steps:1},{repaint:!editing});if(!state.replay.canAdvance||state.engine.status==='blocked')autoAdvance=false;}catch(error){autoAdvance=false;await pauseReplay();toast(errorText(error));}},4000);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&autoAdvance){autoAdvance=false;pauseReplay();}});
window.addEventListener('pagehide',()=>{if(!session||!state||!['starting','running'].includes(state.engine.status))return;autoAdvance=false;fetch('/.netlify/functions/terminal?action=command',{method:'POST',credentials:'same-origin',keepalive:true,headers:{'Content-Type':'application/json','X-CSRF-Token':session.csrfToken},body:JSON.stringify({requestId:crypto.randomUUID(),command:{type:'engine_pause'}})}).catch(()=>{});});
async function start(){try{let fresh=false;try{session=await api('session');}catch(error){if(error.status!==401)throw error;session=await api('guest',{method:'POST',body:{}});fresh=true;}state=session.state;if(!/^\/(en|nb)\//.test(location.pathname))lang=state.settings.language||lang;else if(state.settings.language!==lang){await command({type:'settings_update',settings:{language:lang}},{repaint:false});}if(['starting','running'].includes(state.engine.status)){await command({type:'engine_pause'},{repaint:false});toast(L('Replay paused on reconnect. Start explicitly to continue.','Avspillingen er pauset etter ny tilkobling. Start uttrykkelig for å fortsette.'));}render();fetch('/report-2026/summary.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(data=>{report=data;if(!modal.open)render();}).catch(()=>{});if(fresh)toast(L('Guest ready · virtual USD 100,000 · 1-day session · 7-day retention.','Gjest klar · virtuelle USD 100 000 · økt i 1 døgn · lagring i 7 dager.'));}catch(error){app.innerHTML=`<main class="boot"><a class="brand" href="/${lang}/">NORTIVO</a><h1 class="boot-heading">${L('The workspace could not connect','Arbeidsområdet kunne ikke koble til')}</h1><p>${esc(errorText(error))}</p>${btn(L('Try again','Prøv igjen'),'retry-start','refresh','primary')} <a href="/${lang}/">${L('Return to the website','Tilbake til nettstedet')}</a></main>`;}}
productActive=await startProduct();
if(!productActive)start();
